(817, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'add_showcase_products_202405', '添加橱窗商品', 'This API adds the products to the creator''s showcase. The platform will return the add status of the products, and error code and error message if the deletion fails.', '添加橱窗商品。', 'POST', '/affiliate_creator/202405/showcases/products/add', 1, 0),
(818, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'creator_generate_general_link_202505', '达人生成通用链接', 'You can use this API to generate material sharing links for your publishers. After that, you can encapsulate the sharing link with additional information like publisher ID. Right now, the material type must be `PRODUCT`. Please ensure that the material is included in the campaign by using [Generate Multi Affiliate Partner Campaign Product Links].', '达人生成通用链接。', 'POST', '/affiliate_creator/202505/affiliate_sharing_links/general_publishers/generate_batch', 1, 0),
(819, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'creator_generate_publisher_link_202504', '达人生成发布者链接', 'You can use this API to generate material sharing links for a specific publisher. After that, you can share the link with the publisher. Right now, the material type must be `PRODUCT`. Please ensure that the material is included in the campaign by using [Generate Multi Affiliate Partner Campaign Product Links](generate-multi-affiliate-partner-campaign-product-links).', '达人生成发布者链接。', 'POST', '/affiliate_creator/202504/affiliate_sharing_links/publisher/{publisher_id}/generate_batch', 1, 0),
(820, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'creator_search_affiliate_trace_orders_202505', '达人搜索联盟归因订单', 'This API allows the partner to retrieve a list of affiliate orders generated by a creator, returning the order ID and the product ID. Using this, the partner can track their affiliate-conversions on behalf of a creator, using the order ID.', '达人搜索联盟归因订单。', 'POST', '/affiliate_creator/202505/orders/trace/search', 1, 0),
(821, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'creator_search_open_collaboration_product_202405', '达人搜索公开合作商品', 'This API is used to search the information of products with open collaboration by category, commission rate, and keywords. It will return all products on the TikTok Shop Affiliate Product Marketplace that are in an open collaboration. Creators can only search for open collaboration within the regions they are registered in the affiliate.', '达人搜索公开合作商品。', 'POST', '/affiliate_creator/202405/open_collaborations/products/search', 1, 0),
(822, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'creator_search_sample_application_fulfillments_202409', '达人搜索样品申请履约', 'You, the creator, can use this API to query the fulfillment status for the received sample applications.', '达人搜索样品申请履约。', 'POST', '/affiliate_creator/202409/sample_applications/fulfillments/search', 1, 0),
(823, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'get_creator_applicable_sample_label_202412', '查询达人适用样品标签', 'Check if a creator can apply for a sample of a specific product.', '查询达人适用样品标签。', 'GET', '/affiliate_creator/202412/samples/labels', 1, 0),
(824, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'get_creator_profile_202508', '查询达人资料', 'This API gets the creator profile information.', '查询达人资料。', 'GET', '/affiliate_creator/202508/profiles', 1, 0),
(825, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'get_creator_sample_application_detail_202412', '查询达人样品申请详情', 'Get the sample detail of specified sample application.', '查询达人样品申请详情。', 'POST', '/affiliate_creator/202412/sample_applications/single_query', 1, 0),
(826, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'get_open_collaboration_product_list_by_product_ids_202509', '按商品ID查询公开合作商品列表', 'Get Product OpenCollaboration Product List By Product Ids', '按商品ID查询公开合作商品列表。', 'POST', '/affiliate_creator/202509/open_collaborations/products', 1, 0),
(827, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'get_shop_products_202509', '查询店铺商品', 'Developer can utilize this API to search and retrieve products information of shop which is bound by a specific creator with specific keywords.', '查询店铺商品。', 'GET', '/affiliate_creator/202509/shop_products', 1, 0),
(828, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'get_shoppable_video_precheck_result_202601', '查询带货视频预检结果', 'Use this API to get video pre-check result', '查询带货视频预检结果。', 'GET', '/affiliate_creator/202601/videos/precheck_tasks/{task_id}', 1, 0),
(829, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'get_shoppable_video_status_202509', '查询带货视频状态', 'Use this API to get shoppable video posting results.', '查询带货视频状态。', 'GET', '/affiliate_creator/202509/videos/{video_id}/status', 1, 0),
(830, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'get_showcase_products_202405', '查询橱窗商品', 'This API lists the products in the creator''s showcase, paginated by specified page size and iterated through pages by page token for up to 2000 products in the showcase. This API is generally used when a creator would like to view the products in the showcase. The platform will return the product details in the showcase, as well as the products in the livebag if the creator is live streaming.', '查询橱窗商品。', 'GET', '/affiliate_creator/202405/showcases/products', 1, 0),
(831, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'get_toko_product_mappers_202606', '查询Toko商品映射', 'This API for provide TikTok Shop format product id information by using Tokopedia format product id', '查询Toko商品映射。', 'GET', '/affiliate_creator/202606/toko_product_mappers', 1, 0),
(832, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'post_shoppable_photos_202607', '发布带货图片', 'Use this API to post the shoppable photos with uris and metadata.', '发布带货图片。', 'POST', '/affiliate_creator/202607/photos', 1, 0),
(833, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'post_shoppable_video_202607', '发布带货视频', 'Use this API to post the shoppable video.', '发布带货视频。', 'POST', '/affiliate_creator/202607/videos', 1, 0),
(834, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'precheck_video_content_202511', '预检视频内容', 'Use this API to pre-check if there''s any violation in the video and the shoppable content anchor', '预检视频内容。', 'POST', '/affiliate_creator/202511/videos/precheck_task', 1, 0),
(835, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'remove_showcase_products_202409', '移除橱窗商品', 'This API removes the products in the creator''s showcase. The platform will return error code and error message if the deletion fails.', '移除橱窗商品。', 'DELETE', '/affiliate_creator/202409/showcases/products', 1, 0),
(836, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'search_creator_affiliate_orders_202410', '搜索达人联盟订单', 'Search Creator Affiliate Orders This API allows the partner to retrieve a list of affiliate orders generated by a creator, returning the order ID and the product ID. Using this, the partner can track their affiliate-conversions on behalf of a creator, using the order ID.', '搜索达人联盟订单。', 'POST', '/affiliate_creator/202410/orders/search', 1, 0),
(837, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'search_creator_sample_applications_202412', '搜索达人样品申请', 'Get sample application list of creator.', '搜索达人样品申请。', 'POST', '/affiliate_creator/202412/sample_applications/search', 1, 0),
(838, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'search_creator_target_collaborations_202405', '搜索达人定向合作', 'This API is used to search for creator''s target collaborations and the products within these target collaborations.', '搜索达人定向合作。', 'POST', '/affiliate_creator/202405/target_collaborations/search', 1, 0),
(839, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'search_music_202602', '搜索音乐', 'Use this api to get music info.', '搜索音乐。', 'GET', '/affiliate_creator/202602/music/search', 1, 0),
(840, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'toko_product_mapper_v2_202607', 'Toko商品映射V2', 'This API for provide TikTok Shop format product id information by using Tokopedia format product id', 'Toko商品映射V2。', 'POST', '/affiliate_creator/202607/map_toko_product', 1, 0),
(841, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'top_showcase_products_202409', '置顶橱窗商品', 'Use this API to move products to the top in a creator''s showcase. The platform will return the error code and error message if the pinning operation fails.', '置顶橱窗商品。', 'POST', '/affiliate_creator/202409/showcases/products/top', 1, 0),
(842, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'upload_shoppable_photo_file_202511', '上传带货图片文件', 'Use this API to upload the photos before photo posting. It returns the photo_file_uri for each uploaded image', '上传带货图片文件。', 'POST', '/affiliate_creator/202511/photos/photo_files', 1, 0),
(843, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-creator', '联盟达人', 'upload_shoppable_video_file_202505', '上传带货视频文件', 'Use this API to upload the video before posting to TikTok', '上传带货视频文件。', 'POST', '/affiliate_creator/202505/videos/video_files', 1, 0),
(844, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-partner', '联盟合作伙伴', 'create_affiliate_partner_campaign_202405', '创建联盟合作伙伴活动', 'This API offers the ability to create a campaign for targeted sellers/public sellers, including campaign period, campaign registration period and commission requirements. Note: The campaign will not be displayed to sellers after creation', '创建联盟合作伙伴活动。', 'POST', '/affiliate_partner/202405/campaigns', 1, 0),
(845, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-partner', '联盟合作伙伴', 'edit_affiliate_partner_campaign_202405', '编辑联盟合作伙伴活动', 'This API offers the ability to edit an Affiliate Partner campaign. No editing after the campaign is closed.', '编辑联盟合作伙伴活动。', 'POST', '/affiliate_partner/202405/campaigns/{campaign_id}/partial_edit', 1, 0),
(846, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-partner', '联盟合作伙伴', 'generate_affiliate_partner_campaign_product_link_202405', '生成联盟合作伙伴活动商品链接', 'This API offers the ability to generate campaign product promotion links.', '生成联盟合作伙伴活动商品链接。', 'POST', '/affiliate_partner/202405/campaigns/{campaign_id}/products/{product_id}/promotion_link/generate', 1, 0),
(847, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-partner', '联盟合作伙伴', 'get_affiliate_campaign_creator_fulfillment_status_info_202508', '查询联盟活动达人履约状态详情', 'This API offers the ability to get the product fulfillment status for creators who added partner campaign products to their showcase', '查询联盟活动达人履约状态详情。', 'GET', '/affiliate_partner/202508/campaigns/{campaign_id}/products/{product_id}/performance', 1, 0),
(848, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-partner', '联盟合作伙伴', 'get_affiliate_campaign_creator_fulfillment_status_list_202501', '查询联盟活动达人履约状态列表', 'This API offers the ability to get the product of the campaign fulfillment status for creators who added partner campaign products to their showcase. For details of a specified product involved in an affiliated campaign, use Get Affiliate Campaign Creator Fulfillment Status Info gateway.', '查询联盟活动达人履约状态列表。', 'GET', '/affiliate_partner/202501/campaigns/{campaign_id}/products/performance', 1, 0),
(849, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-partner', '联盟合作伙伴', 'get_affiliate_campaign_creator_product_content_statistics_202508', '查询联盟活动达人商品内容统计', 'Get statistics on creator''s marketing video content', '查询联盟活动达人商品内容统计。', 'GET', '/affiliate_partner/202508/campaigns/{campaign_id}/products/{product_id}/creator/{creator_temp_id}/content/statistics', 1, 0),
(850, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-partner', '联盟合作伙伴', 'get_affiliate_campaign_creator_product_sample_status_202508', '查询联盟活动达人商品样品状态', 'Get progress on creator''s sample status', '查询联盟活动达人商品样品状态。', 'GET', '/affiliate_partner/202508/campaigns/{campaign_id}/products/{product_id}/creator/{creator_temp_id}/content/statistics/sample/status', 1, 0),
(851, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-partner', '联盟合作伙伴', 'get_affiliate_partner_campaign_detail_202405', '查询联盟合作伙伴活动详情', 'This API offers the ability to get affiliate campaign details.', '查询联盟合作伙伴活动详情。', 'GET', '/affiliate_partner/202405/campaigns/{campaign_id}', 1, 0),
(852, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-partner', '联盟合作伙伴', 'get_affiliate_partner_campaign_list_202405', '查询联盟合作伙伴活动列表', 'This API offers the ability to list campaigns created by the Affiliate Partner.', '查询联盟合作伙伴活动列表。', 'GET', '/affiliate_partner/202405/campaigns', 1, 0),
(853, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-partner', '联盟合作伙伴', 'get_affiliate_partner_campaign_product_list_202405', '查询联盟合作伙伴活动商品列表', 'This API offers the ability to list products submitted by sellers in an Affiliate Partner campaign.', '查询联盟合作伙伴活动商品列表。', 'GET', '/affiliate_partner/202405/campaigns/{campaign_id}/products', 1, 0),
(854, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-partner', '联盟合作伙伴', 'partner_generate_multi_affiliate_campaign_product_link_202505', '合作伙伴生成批量联盟活动商品链接', 'This API offers the ability to generate promotion links for multiple products in a campaign.', '合作伙伴生成批量联盟活动商品链接。', 'POST', '/affiliate_partner/202505/campaigns/{campaign_id}/products/promotion_links/generate_batch', 1, 0),
(855, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-partner', '联盟合作伙伴', 'publish_affiliate_partner_campaign_202405', '发布联盟合作伙伴活动', 'This API offers the ability to publish an Affiliate Partner campaign. The campaign will be displayed to sellers after publishing.', '发布联盟合作伙伴活动。', 'POST', '/affiliate_partner/202405/campaigns/{campaign_id}/publish', 1, 0),
(856, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-partner', '联盟合作伙伴', 'review_affiliate_partner_campaign_product_202405', '审核联盟合作伙伴活动商品', 'This API offers the ability for the TikTok Affiliate Partner to review the products submitted by the sellers. This API offers the ability for the TikTok Affiliate Partner to review the products submitted by the sellers.', '审核联盟合作伙伴活动商品。', 'POST', '/affiliate_partner/202405/campaigns/{campaign_id}/products/{product_id}/review', 1, 0),
(857, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-partner', '联盟合作伙伴', 'search_cap_affiliate_orders_202603', '搜索CAP联盟订单', 'Search the list of affiliate orders of the specified date range from a MCN or known as CAP - Creator Agency partner', '搜索CAP联盟订单。', 'POST', '/affiliate_partner/202603/cap_order/search', 1, 0),
(858, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-partner', '联盟合作伙伴', 'search_tap_affiliate_orders_202603', '搜索TAP联盟订单', 'TAP can use this API to retrieve a list of affiliate orders and track the affiliate conversions.', '搜索TAP联盟订单。', 'POST', '/affiliate_partner/202603/orders/search', 1, 0),
(859, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'cancel_target_collaboration_conflicts_202605', '取消定向合作冲突', 'Execute resolution actions on resolvable conflict items within the scope of seller authorization.', '取消定向合作冲突。', 'POST', '/affiliate_seller/202605/target_collaborations/conflicts/resolve', 1, 0),
(860, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'check_target_collaboration_conflicts_202605', '检查定向合作冲突', 'Retrieve conflicting target collaborations for the product and determine if they can be terminated', '检查定向合作冲突。', 'POST', '/affiliate_seller/202605/target_collaborations/conflicts/check', 1, 0),
(861, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'create_compass_offline_export_task_202603', '创建Compass离线导出任务', 'Create an asynchronous offline export task for the specified doc_type and plan_type within a given time window. Returns a task_id for subsequent status query and file download.', '创建Compass离线导出任务。', 'POST', '/affiliate_seller/202603/compass/offline_task', 1, 0),
(862, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'create_conversation_with_creator_202508', '与达人创建会话', 'Get the existing conversation or create a new conversation with the specified TikTok creator for later communication.', '与达人创建会话。', 'POST', '/affiliate_seller/202508/conversations', 1, 0),
(863, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'create_open_collaboration_202412', '创建公开合作', 'This API allows the seller to create an open collaboration. You create an open collaboration by selecting products and setting a commission rate.', '创建公开合作。', 'POST', '/affiliate_seller/202412/open_collaborations', 1, 0),
(864, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'create_target_collaboration_202508', '创建定向合作', 'This API is used to create a target collaboration. A target collaboration is a collaboration between a seller selected set of products (including a commission payout) and a set of creators the seller has added (invited) to the collaboration. Target collaborations are private and not visible in the Creator Marketplace to all creators; they are only visible to those that have been added to the collaboration.', '创建定向合作。', 'POST', '/affiliate_seller/202508/target_collaborations', 1, 0),
(865, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'download_compass_task_file_202603', '下载Compass任务文件', 'Download the result file of a completed export task by taskId. Requires ownership validation; returns file.', '下载Compass任务文件。', 'GET', '/affiliate_seller/202603/compass/offline_tasks/{task_id}/file', 1, 0),
(866, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'edit_open_collaboration_sample_rule_202410', '编辑公开合作样品规则', 'Use this API to manage sample rules in open collaborations, like valid time periods, or thresholds for creators to request samples. You can create, update, or deactivate rules.', '编辑公开合作样品规则。', 'POST', '/affiliate_seller/202410/open_collaborations/sample_rules', 1, 0),
(867, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'edit_open_collaboration_settings_202405', '编辑公开合作设置', 'This API is used to edit a Seller''s open collaboration settings. It allows you to enroll your existing product catalog and all future products into an open collaboration plan. It also allows you to turn this setting off at any point. By default, this option is turned off for all Sellers.', '编辑公开合作设置。', 'POST', '/affiliate_seller/202405/open_collaboration_settings', 1, 0),
(868, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'generate_affiliate_product_promotion_link_202405', '生成联盟商品推广链接', 'The user of this API is a partner developer, on behalf of Sellers. This API is used to generate affiliate exclusive product link based on all open collaboration products available within the TikTok Shop Affiliate Product Marketplace. This API generates a link, at the product ID level (which belongs to a Seller). This link, can be distributed to creators, by the partner developer(the user of this API). The creator adds this product to the creators'' showcase through this url. This link, represents an affiliate partner''s ability to bring higher matchmaking effectiveness on behalf of a seller. If a creator does indeed add the product to showcase through this link, then the downstream consumer purchases will be able to be attributed to this partner due to the link generation capabilities.', '生成联盟商品推广链接。', 'POST', '/affiliate_seller/202405/products/{product_id}/promotion_link/generate', 1, 0),
(869, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'generate_target_collaboration_link_202509', '生成定向合作链接', 'Generate a Target Collaboration Link that the seller can share with the creator. This link directs the creator to a guided flow to review details and formally accept the target collaboration', '生成定向合作链接。', 'POST', '/affiliate_seller/202509/target_collaboration/{target_collaboration_id}/link', 1, 0),
(870, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'get_compass_task_list_202603', '查询Compass任务列表', 'Retrieve the list of export tasks created via Open API for the authorized seller (last 7 days). Supports pagination and returns task status, file_name and timestamps.', '查询Compass任务列表。', 'GET', '/affiliate_seller/202603/compass/offline_tasks', 1, 0),
(871, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'get_conversation_list_202412', '查询会话列表', 'Get User''s Conversation list.', '查询会话列表。', 'GET', '/affiliate_seller/202412/conversations', 1, 0),
(872, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'get_inbox_category_counts_202608', '查询收件箱类目数量', 'Query the number of sessions grouped by status such as read, unread, starred and archived.', '查询收件箱类目数量。', 'GET', '/affiliate_seller/202608/conversations/group_counts', 1, 0),
(873, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'get_latest_unread_messages_202412', '查询最新未读消息', 'Get the unread messages from the last minute. You are recommended to use the Webhook, New Message Listener, for the message notification.', '查询最新未读消息。', 'GET', '/affiliate_seller/202412/conversations/messages/list/newest', 1, 0),
(874, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'get_marketplace_creator_performance_202608', '查询达人市场表现', 'Get the Creator Affiliate''s Marketplace information and performance metrics in the last 30 days.', '查询达人市场表现。', 'GET', '/affiliate_seller/202608/marketplace_creators/{creator_user_id}', 1, 0),
(875, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'get_message_in_the_conversation_202412', '查询会话中的消息', 'Get chat history in one conversation.', '查询会话中的消息。', 'GET', '/affiliate_seller/202412/conversation/{conversation_id}/messages', 1, 0),
(876, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'get_open_collaboration_creator_content_detail_202508', '查询公开合作达人内容详情', 'This API allows the seller to get the creator content details of specified open collaboration.', '查询公开合作达人内容详情。', 'GET', '/affiliate_seller/202508/open_collaborations/creator_content_details', 1, 0),
(877, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'get_open_collaboration_sample_rules_202410', '查询公开合作样品规则', 'Use this API to get the status and the details of the sample rules for products under an open collaboration. With this API, you can efficiently review the sample distribution criteria for products within the open collaboration context.', '查询公开合作样品规则。', 'GET', '/affiliate_seller/202410/open_collaborations/sample_rules', 1, 0),
(878, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'get_open_collaboration_settings_202409', '查询公开合作设置', 'Get the open collaboration settings, including auto add settings.', '查询公开合作设置。', 'GET', '/affiliate_seller/202409/open_collaboration_settings', 1, 0),
(879, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'get_seller_search_creator_marketplace_advanced_filters_202608', '查询卖家搜索达人市场的高级筛选条件', 'This API allows you to obtain the advanced filters available in Seller Search Creator Marketplace. Because we are constantly releasing new filters which are specific to each country or region, this API serves as a way for developers to retrieve the latest available search filters.', '查询卖家搜索达人市场的高级筛选条件。', 'POST', '/affiliate_seller/202608/marketplace_creators/search/filter', 1, 0),
(880, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'get_weekly_creator_outreach_quota_202607', '查询每周达人邀约配额', 'Query the weekly outreach invitation quota for a shop. It returns the current GMV tier, maximum reachable creator follower count corresponding to the tier, consumed quota, remaining quota and other related information.', '查询每周达人邀约配额。', 'GET', '/affiliate_seller/202607/creator_outreach/quota', 1, 0),
(881, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'get_weekly_creator_outreach_records_202608', '查询每周达人邀约记录', 'Query weekly detailed outreach‑invitation records for a specified seller, including whether IM messages/invitations were sent to a unconnected creator, and whether the creator added products or replied to IM messages.', '查询每周达人邀约记录。', 'POST', '/affiliate_seller/202608/creator_outreach/records/query', 1, 0),
(882, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'mark_conversation_read_202412', '标记会话为已读', 'Mark the messages in the specified conversations to be read.', '标记会话为已读。', 'POST', '/affiliate_seller/202412/conversatons/read', 1, 0),
(883, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'query_creator_promotion_details_in_target_collaboration_202608', '查询定向合作中的达人推广详情', 'Query the creator commission rate, number of promotional video contents and number of live‑stream promotions for specified creator, specified invitation and specified product.', '查询定向合作中的达人推广详情。', 'POST', '/affiliate_seller/202608/target_collaborations/creator_promotion_details/query', 1, 0),
(884, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'query_target_collaboration_detail_202508', '查询定向合作详情', 'This API is used by Sellers to get target collaboration information.', '查询定向合作详情。', 'GET', '/affiliate_seller/202508/target_collaborations/{target_collaboration_id}', 1, 0),
(885, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'remove_creator_from_open_collaboration_202508', '从公开合作中移除达人', 'This API is used to remove creators from open collaboration. Please note, due to current platform design, creators can still rejoin an open collaboration after removal. Partners/Sellers can call this API again to remove the creator again.', '从公开合作中移除达人。', 'POST', '/affiliate_seller/202508/open_collaborations/{open_collaboration_id}/remove_creator', 1, 0),
(886, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'remove_open_collaboration_202409', '移除公开合作', 'Remove open collaboration for product. You can only remove open collaboration when `status==NORMAL`. When you call this API, the open collaborations will be terminated at `terminated_effective_time`, not immediately, to protect the interests of the creators. After `terminated_effective_time`, the open collaboration is officially terminated and can not be found in the response in [Search Open Collaboration].', '移除公开合作。', 'DELETE', '/affiliate_seller/202409/open_collaborations/products/{product_id}', 1, 0),
(887, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'remove_target_collaboration_202409', '移除定向合作', 'This API is used by Seller to remove affiliate target collaboration.', '移除定向合作。', 'DELETE', '/affiliate_seller/202409/target_collaborations/{target_collaboration_id}', 1, 0),
(888, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'search_open_collaboration_202412', '搜索公开合作', 'Retrieve all open collaboration information from merchants, including commission rate, add to showcase and post content creator count.', '搜索公开合作。', 'POST', '/affiliate_seller/202412/open_collaborations/search', 1, 0),
(889, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'search_seller_affiliate_orders_202410', '搜索卖家联盟订单', 'This API allows the partner to retrieve a list of affiliate orders (orders which are affiliate-commission eligible) generated by a seller, returning the order ID and the product ID. Using this, the partner can track their affiliate-conversions on behalf of a seller, using the order ID.', '搜索卖家联盟订单。', 'POST', '/affiliate_seller/202410/orders/search', 1, 0),
(890, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'search_target_collaborations_202508', '搜索定向合作', 'This API is used by Seller to search for all existing target collaborations. Sellers can search based on filters such as Invitation name, Invitation ID, Product name, Product ID and Creator name.', '搜索定向合作。', 'POST', '/affiliate_seller/202508/target_collaborations/search', 1, 0),
(891, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'seller_get_sample_request_deeplink_202512', '卖家查询样品申请深链', 'Use this API to get a TikTok deeplink, use this deeplink to launch the TikTok app and land the user on the sample request page. * The seller can encode the deeplink into an QR code and send it to a creator via email.', '卖家查询样品申请深链。', 'GET', '/affiliate_seller/202512/sample_applications/deeplink', 1, 0),
(892, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'seller_review_sample_applications_202507', '卖家审核样品申请', 'This API allows the seller to approve or reject the creator''s sample application in an open collaboration. When rejecting an application, the seller must provide a specific reason. This API facilitates the management of sample applications by giving sellers the ability to review and update applications according to their criteria and requirements.', '卖家审核样品申请。', 'POST', '/affiliate_seller/202507/sample_applications/{application_id}/review', 1, 0),
(893, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'seller_search_affiliate_open_collaboration_product_202405', '卖家搜索联盟公开合作商品', 'This API is used to search the information of products with open collaboration by category, commission rate, and keywords. It will return all products on the TikTok Shop Affiliate Product Marketplace that are in an open collaboration. Sellers can only search for open collaboration within the regions they are registered to sell in.', '卖家搜索联盟公开合作商品。', 'POST', '/affiliate_seller/202405/open_collaborations/products/search', 1, 0),
(894, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'seller_search_creator_on_marketplace_202608', '卖家搜索达人市场中的达人', 'This API is used by Sellers to search for Creators in the Creator Marketplace. Sellers can search based on filters such as GMV, keywords, and Creator follower demographics. All the data returned is for the last 30 days.', '卖家搜索达人市场中的达人。', 'POST', '/affiliate_seller/202608/marketplace_creators/search', 1, 0),
(895, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'seller_search_sample_applications_202508', '卖家搜索样品申请', 'This API is provided for sellers to query sample applications based on various criteria such as products, creators, or application statuses. By using this API, sellers can retrieve detailed information about sample application records, including the creator''s information and the specifics of each application.', '卖家搜索样品申请。', 'POST', '/affiliate_seller/202508/sample_applications/search', 1, 0),
(896, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'seller_search_sample_applications_fulfillments_202409', '卖家搜索样品申请履约', 'You, the seller, can use this API to get the fulfillment status of the specific sample application and whether the fulfillment resulted in orders. This allows Sellers to track the current progress or analyze the results of their sample distribution program.', '卖家搜索样品申请履约。', 'POST', '/affiliate_seller/202409/sample_applications/{application_id}/fulfillments/search', 1, 0),
(897, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'send_im_message_202412', '发送即时通讯消息', 'The API for sending IM messages.', '发送即时通讯消息。', 'POST', '/affiliate_seller/202412/conversations/{conversation_id}/messages', 1, 0),
(898, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'update_conversation_status_202608', '更新会话状态', 'Support starring or archiving a given conversation with creator.', '更新会话状态。', 'POST', '/affiliate_seller/202608/conversations/{conversation_id}/status', 1, 0),
(899, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'update_target_collaboration_202508', '更新定向合作', 'This API is used by Seller to update STANDARD target collaboration.', '更新定向合作。', 'PUT', '/affiliate_seller/202508/target_collaborations/{target_collaboration_id}', 1, 0),
(900, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'upload_message_image_202511', '上传消息图片', 'You must use this API to upload the image first, before sending an image as a message using [Send IM Messsage](https://partner.tiktokshop.com/docv2/page/send-im-message-202412)', '上传消息图片。', 'POST', '/affiliate_seller/202511/images/upload', 1, 0),
(901, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'affiliate-seller', '联盟卖家', 'upload_message_image_v2_202608', '上传消息图片V2', 'You must use this API to upload the image first, before sending an image as a message using [Send IM Messsage](https://partner.tiktokshop.com/docv2/page/send-im-message-202412)', '上传消息图片V2。', 'POST', '/affiliate_seller/202608/media/upload', 1, 0),
(902, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_bestselling_creators_202511', '查询畅销达人', 'Get the top 100 performing creators of the target date range', '查询畅销达人。', 'GET', '/analytics/202511/creators/bestselling', 1, 0),
(903, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_bestselling_live_sessions_202511', '查询畅销直播场次', 'Get the top 100 performing lives of the target date range', '查询畅销直播场次。', 'GET', '/analytics/202511/lives/bestselling', 1, 0),
(904, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_bestselling_products_202511', '查询畅销商品', 'Get the top 100 performing products of the target date range', '查询畅销商品。', 'GET', '/analytics/202511/products/bestselling', 1, 0),
(905, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_bestselling_videos_202511', '查询畅销视频', 'Get the top 100 performing videos of the target date range', '查询畅销视频。', 'GET', '/analytics/202511/videos/bestselling', 1, 0),
(906, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_live_room_core_stats_202502', '查询直播间核心指标', 'Returns core stats for the specified live room, including GMV, order counts, buyer counts, product click counts, and view counts.', '查询直播间核心指标。', 'GET', '/analytics/202502/live_rooms/{live_room_id}/core_stats', 1, 0),
(907, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_live_room_gmv_trend_202502', '查询直播间GMV趋势', 'Returns GMV trend performance points for the specified live room, including GMV and created-order trend values.', '查询直播间GMV趋势。', 'GET', '/analytics/202502/live_rooms/{live_room_id}/gmv_trend_performances', 1, 0),
(908, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_live_room_interactive_trends_202502', '查询直播间互动趋势', 'Returns interactive trend performance points for the specified live room, including watch, comment, and share counts.', '查询直播间互动趋势。', 'GET', '/analytics/202502/live_rooms/{live_room_id}/interactive_trend_performances', 1, 0),
(909, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_live_room_product_stats_202502', '查询直播间商品指标', 'Returns the product list for the specified live room, including product IDs, names, GMV, unit price, inventory counts, and click counts.', '查询直播间商品指标。', 'GET', '/analytics/202502/live_rooms/{live_room_id}/product_stats', 1, 0),
(910, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_live_room_traffic_performance_202502', '查询直播间流量表现', 'Returns traffic performance for the specified live room, including source and sub-source watch counts for distribution analysis.', '查询直播间流量表现。', 'GET', '/analytics/202502/live_rooms/{live_room_id}/traffic_performances', 1, 0),
(911, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_live_room_user_portraits_202502', '查询直播间用户画像', 'Returns user portrait indicators for the specified live room, including age, gender, fan, advertisement, and region distributions.', '查询直播间用户画像。', 'GET', '/analytics/202502/live_rooms/{live_room_id}/user_portraits', 1, 0),
(912, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_live_room_view_trends_202502', '查询直播间观看趋势', 'Returns viewer count trend data points for the specified live room, grouped by online, entering, and leaving viewers.', '查询直播间观看趋势。', 'GET', '/analytics/202502/live_rooms/{live_room_id}/view_trend_performances', 1, 0),
(913, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_shop_live_minute_performance_202510', '查询店铺直播分钟级表现', 'Returns minute-level performance for a LIVE session after the session is finished. This API only returns data for live streams hosted by the shop official account or marketing account.', '查询店铺直播分钟级表现。', 'GET', '/analytics/202510/shop_lives/{live_id}/performance_per_minutes', 1, 0),
(914, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_shop_live_performance_list_202509', '查询店铺直播表现列表', 'Returns a list of LIVE stream sessions and associated metrics for a shop. Sellers can only query room ID data for their own official creator accounts.', '查询店铺直播表现列表。', 'GET', '/analytics/202509/shop_lives/performance', 1, 0),
(915, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_shop_live_performance_overview_202509', '查询店铺直播表现概览', 'Returns overall performance metrics for all LIVE stream sessions under a certain shop.', '查询店铺直播表现概览。', 'GET', '/analytics/202509/shop_lives/overview_performance', 1, 0),
(916, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_shop_live_products_performance_list_202512', '查询店铺直播商品表现列表', 'Returns sale performance for each product in a shop-related LIVE session from the official account or marketing accounts.', '查询店铺直播商品表现列表。', 'GET', '/analytics/202512/shop/{live_id}/products_performance', 1, 0),
(917, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_shop_performance_202509', '查询店铺表现', 'Returns performance metrics at shop/seller level.', '查询店铺表现。', 'GET', '/analytics/202509/shop/performance', 1, 0),
(918, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_shop_performance_per_hour_202510', '查询店铺每小时表现', 'Returns hourly shop performance details for the requested date. The date can be within the last 30 days, including today.', '查询店铺每小时表现。', 'GET', '/analytics/202510/shop/performance/{date}/performance_per_hour', 1, 0),
(919, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_shop_product_performance_detail_202509', '查询店铺商品表现详情', 'Returns detailed performance metrics for the specified product.', '查询店铺商品表现详情。', 'GET', '/analytics/202509/shop_products/{product_id}/performance', 1, 0),
(920, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_shop_product_performance_list_202605', '查询店铺商品表现列表', 'Returns a list of product performance overview metrics.', '查询店铺商品表现列表。', 'GET', '/analytics/202605/shop_products/performance', 1, 0),
(921, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_shop_sku_performance_detail_202509', '查询店铺SKU表现详情', 'Returns performance metrics for the specified SKU.', '查询店铺SKU表现详情。', 'GET', '/analytics/202509/shop_skus/{sku_id}/performance', 1, 0),
(922, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_shop_sku_performance_list_202509', '查询店铺SKU表现列表', 'Returns a list of SKU performance metrics.', '查询店铺SKU表现列表。', 'GET', '/analytics/202509/shop_skus/performance', 1, 0),
(923, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_shop_video_performance_details_202509', '查询店铺视频表现详情', 'Returns detailed performance metrics for a (requested) video.', '查询店铺视频表现详情。', 'GET', '/analytics/202509/shop_videos/{video_id}/performance', 1, 0),
(924, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_shop_video_performance_list_202605', '查询店铺视频表现列表', 'Returns a list of videos and associated metrics for a shop.', '查询店铺视频表现列表。', 'GET', '/analytics/202605/shop_videos/performance', 1, 0),
(925, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_shop_video_performance_overview_202509', '查询店铺视频表现概览', 'Returns overall performance metrics for all videos under a shop.', '查询店铺视频表现概览。', 'GET', '/analytics/202509/shop_videos/overview_performance', 1, 0),
(926, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_shop_video_product_performance_list_202509', '查询店铺视频商品表现列表', 'Returns performance metrics for a list of products promoted in a given video.', '查询店铺视频商品表现列表。', 'GET', '/analytics/202509/shop_videos/{video_id}/products/performance', 1, 0),
(927, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_sps_metric_diagnosis_202606', '查询SPS指标诊断', 'Returns diagnosis details for a single SPS metric, including benchmark thresholds, trends, calculation details, and distribution details. Supported only for US-region shops.', '查询SPS指标诊断。', 'GET', '/analytics/202606/shop_performances/metrics/{metric_code}/diagnosis', 1, 0),
(928, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_sps_metric_problem_details_202606', '查询SPS指标问题详情', 'Returns problem order or chat details for a selected SPS metric. Supported only for US-region shops.', '查询SPS指标问题详情。', 'GET', '/analytics/202606/shop_performances/metrics/{metric_code}/problem_details', 1, 0),
(929, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_sps_metric_top_items_202606', '查询SPS指标重点项目', 'Returns top products, logistics providers, or aftersales types for a selected SPS metric. Supported only for US-region shops.', '查询SPS指标重点项目。', 'GET', '/analytics/202606/shop_performances/metrics/{metric_code}/top_items', 1, 0),
(930, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_sps_metrics_202606', '查询SPS指标', 'Returns SPS metric details and benchmark thresholds for the authorized shop. Supported only for US-region shops.', '查询SPS指标。', 'GET', '/analytics/202606/shop_performances/metrics', 1, 0),
(931, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_sps_overview_202606', '查询SPS概览', 'Returns the SPS overview for the authorized shop, including the score, tier, dimensions, benefits, and top issues. Supported only for US-region shops.', '查询SPS概览。', 'GET', '/analytics/202606/shop_performances/overview', 1, 0),
(932, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'analytics', '数据分析', 'get_video_performances_202403', '查询视频表现', 'Use this US-creator-only API to retrieve TikTok e-commerce video metrics, including anchor_display_rate, click_through_rate, orders, items_sold, and GMV, for the requested videos.', '查询视频表现。', 'GET', '/analytics/202403/videos/performances', 1, 0),
(933, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'authorization', '授权', 'get_authorized_category_assets_202405', '查询已授权类目资产', 'Retrieves the list of business category assets authorized by a partner for an app. Partner authorization is required before an app can access the data of a partner, and this access is granted based on business categories. Use this API to check which business category assets are currently authorized for an app and obtain the corresponding category asset cipher for use as an input parameter in affiliate partner related APIs. For more information about partner authorization, refer to [Partner authorization guide](678e3a3978f4c20311b8b555). Target partner: All', '查询已授权类目资产。', 'GET', '/authorization/202405/category_assets', 1, 0),
(934, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'authorization', '授权', 'get_authorized_shops_202309', '查询已授权店铺', 'Retrieves the list of shops that a seller has authorized for an app. Seller authorization is required before an app can access the data of a shop. Use this API to check which shops are currently authorized for an app and obtain the corresponding shop cipher for use as an input parameter in shop related APIs. For more information about seller authorization, refer to [Seller authorization guide](https://partner.tiktokshop.com/docv2/page/678e3a344ddec3030b238fa0). Target seller: All', '查询已授权店铺。', 'GET', '/authorization/202309/shops', 1, 0),
(935, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'customer-engagement', '用户触达', 'create_custom_engagement_task_202502', '创建自定义用户触达任务', 'Create an engagement task that uses a self-defined custom message instead of predefined message templates from TikTok Shop. The task acts as a container for grouping messages with similar content and rules, allowing sellers to track and compare task performance across different types of content. Note that each task has a mandatory end time, and once expired, it cannot be used to send additional messages.', '创建自定义用户触达任务。', 'POST', '/customer_engagement/202502/engagement_tasks/custom', 1, 0),
(936, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'customer-engagement', '用户触达', 'create_engagement_task_202412', '创建用户触达任务', 'Create an engagement task that acts as a container for grouping messages with similar content and rules, allowing sellers to track and compare task performance across different types of content. Note that each task has a mandatory end time, and once expired, it cannot be used to send additional messages.', '创建用户触达任务。', 'POST', '/customer_engagement/202412/engagement_tasks', 1, 0),
(937, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'customer-engagement', '用户触达', 'get_engagement_feature_permissions_202502', '查询用户触达功能权限', 'Retrieve information about customer engagement features that the shop has permission to use.', '查询用户触达功能权限。', 'GET', '/customer_engagement/202502/permissions', 1, 0),
(938, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'customer-engagement', '用户触达', 'get_engagement_task_performances_202412', '查询用户触达任务表现', 'Retrieve detailed performance metrics for a customer engagement task, including message reads, order conversions, and other key engagement statistics.', '查询用户触达任务表现。', 'POST', '/customer_engagement/202412/performances', 1, 0),
(939, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'customer-engagement', '用户触达', 'get_message_templates_202412', '查询消息模板', 'Get a library of customer engagement message templates predefined by TikTok Shop, which you can use directly in your customer engagement communications.', '查询消息模板。', 'GET', '/customer_engagement/202412/message_templates', 1, 0),
(940, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'customer-engagement', '用户触达', 'send_engagement_message_202412', '发送用户触达消息', 'Send messages to specific customers for a particular engagement task.', '发送用户触达消息。', 'POST', '/customer_engagement/202412/messages', 1, 0),
(941, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'customer-service', '客服', 'create_conversation_202309', '创建会话', 'Use this API to create a conversation with the specified buyer, on behalf of a shop. When there''s no prior conversation, calling this API creates a new conversation; when there''s a prior conversation, no matter whether it''s active, finished, or closed, calling this API reopens the conversation and returns the same conversation ID as the prior one.', '创建会话。', 'POST', '/customer_service/202309/conversations', 1, 0),
(942, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'customer-service', '客服', 'end_session_202605', '结束会话', 'Use this API to end an active customer service session assigned to an agent.', '结束会话。', 'POST', '/customer_service/202605/conversations/{conversation_id}/sessions/{session_id}/end', 1, 0),
(943, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'customer-service', '客服', 'get_agent_settings_202309', '查询客服人员设置', 'This API is used to get agent settings. This API allows the agent to see whether the agent can accept chats from buyers. This API is a read-only endpoint. There will be no side effects, and can be retried safely. Note: 1. The current API version can only get settings on behalf of the shop, or the owner account holder on Seller Center. The owner in this case is acting as the customer service agent. In the future, we plan to make this API available to subaccount holders (who has customer service role) in Seller Center. 2. This API is to allow the agent to get his/her own setting. See more information in API overview', '查询客服人员设置。', 'GET', '/customer_service/202309/agents/settings', 1, 0),
(944, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'customer-service', '客服', 'get_conversation_202601', '查询会话', 'Use this API to retrieve information about a conversation by ID.', '查询会话。', 'GET', '/customer_service/202601/conversations/{conversation_id}', 1, 0),
(945, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'customer-service', '客服', 'get_conversation_messages_202309', '查询会话消息', 'Use this API to get all messages in a conversation between a buyer and a shop. Calling this API does not mark the messages as read. You are suggested to call [Read Message](650a59f7c16ffe02b8e8db3f) to mark the messages read.', '查询会话消息。', 'GET', '/customer_service/202309/conversations/{conversation_id}/messages', 1, 0),
(946, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'customer-service', '客服', 'get_conversations_202309', '查询会话', 'Use this API to retrieve a shop''s conversations with buyers.', '查询会话。', 'GET', '/customer_service/202309/conversations', 1, 0),
(947, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'customer-service', '客服', 'get_customer_service_performance_202407', '查询客服表现', 'Get the average customer service performance of a shop for a selected time period', '查询客服表现。', 'GET', '/customer_service/202407/performance', 1, 0),
(948, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'customer-service', '客服', 'read_message_202309', '标记消息已读', 'Use this API to mark all messages sent by the buyer as read. You are suggested to call this API before replying to their messages.', '标记消息已读。', 'POST', '/customer_service/202309/conversations/{conversation_id}/messages/read', 1, 0),
(949, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'customer-service', '客服', 'search_sessions_202602', '搜索会话', 'Description of [POST]/customer_service/:version/sessions', '搜索会话。', 'POST', '/customer_service/202602/sessions/search', 1, 0),
(950, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'customer-service', '客服', 'send_message_202606', '发送消息', 'Use this API to send a message to the buyer in a conversation.', '发送消息。', 'POST', '/customer_service/202606/conversations/{conversation_id}/messages', 1, 0),
(951, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'customer-service', '客服', 'update_agent_settings_202309', '更新客服人员设置', 'Use this API to update agent status on behalf of the agent. Agents can set whether they can accept auto assigned chats. Before using API, we recommend setting can_accept_chat to true, in order to accept chats. Note: 1. The current API version can only update settings on behalf of the shop, or the owner account holder on Seller Center. The owner in this case is acting as the customer service agent. In the future, we plan to make this API available to subaccount holders (who has customer service role) in Seller Center. 2. This API is to allow the agent to update their own setting. See more information in API overview', '更新客服人员设置。', 'PUT', '/customer_service/202309/agents/settings', 1, 0),
(952, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'customer-service', '客服', 'upload_buyer_messages_image_202309', '上传买家消息图片', 'You must use this API to upload the image first, before sending an image as a message using [Send Message](650a58bbbace3e02b7556286).', '上传买家消息图片。', 'POST', '/customer_service/202309/images/upload', 1, 0),
(953, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'event', '事件', 'delete_shop_webhook_202309', '删除店铺Webhook', 'Deletes the shop''s webhook URL for a specific event topic. Regardless of whether webhook is configured or not, the result will return success.', '删除店铺Webhook。', 'DELETE', '/event/202309/webhooks', 1, 0),
(954, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'event', '事件', 'get_shop_webhooks_202309', '查询店铺Webhook', 'Retrieves a shop''s webhooks and the corresponding webhook URLs.', '查询店铺Webhook。', 'GET', '/event/202309/webhooks', 1, 0),
(955, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'event', '事件', 'update_shop_webhook_202309', '更新店铺Webhook', 'Updates the shop''s webhook URL for a specific event topic.', '更新店铺Webhook。', 'PUT', '/event/202309/webhooks', 1, 0),
(956, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'finance', '财务', 'get_payments_202605', '查询付款', '**This API is currently unavailable to SEA markets.** Retrieves records of automated payments for a shop based on a specified date range. Use the returned list to verify and reconcile payments with the transactions in the seller''s bank account.', '查询付款。', 'GET', '/finance/202605/payments', 1, 0),
(957, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'finance', '财务', 'get_statements_202309', '查询结算单', 'Retrieves the statements generated for a shop and the key statement information based on a specified date range or their payment status. Use this API to get an overview of your daily statements over a range of time, or to find out which statements have been paid or not. For the detailed transactions, refer to [Get Statement Transactions](650a6749defece02be67da87) or [Get Order Statement Transactions](650a6734defece02be67d724). Applicable for all regions'' sellers. Only data after 2023-07-01 is available.', '查询结算单。', 'GET', '/finance/202309/statements', 1, 0),
(958, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'finance', '财务', 'get_transactions_by_order_202501', '按订单查询交易', 'Retrieves the SKU-level details of an order transaction. This covers transactions related to sales, fees, commissions, shipping, taxes, and refunds. Applicable for all regions'' sellers. Only data after 2023-07-01 is available (Please note that for US cross-border sellers, data before 2025-04-30 is unavailable).', '按订单查询交易。', 'GET', '/finance/202501/orders/{order_id}/statement_transactions', 1, 0),
(959, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'finance', '财务', 'get_transactions_by_statement_202501', '按结算单查询交易', 'Retrieves the details of a statement, including the transactions, which can be a standard order transaction, an adjustment transaction, or a reserve-related transaction. For the SKU-level details of an order transaction, refer to [Get Transactions by Order](650a6734defece02be67d724). Applicable for all regions'' sellers. Only data after 2023-07-01 is available (Please note that for US cross-border sellers, data before 2025-04-30 is unavailable).', '按结算单查询交易。', 'GET', '/finance/202501/statements/{statement_id}/statement_transactions', 1, 0),
(960, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'finance', '财务', 'get_unsettled_transactions_202507', '查询未结算交易', 'This API allows the partner to retrieve a list of unsettled transactions (incl. Orders & Adjustments) generated by a seller, returning the detailed fee breakdown for a list of order ID and adjustment ID. For now, this API only returns transactions which were created after 2025.01.01. Once one transaction is settled, which won''t be returned by this API anymore, please get from Get Statement Transaction API. **Pay attention to that all data returned through this API is an estimated amount which subject to change before settlement and can only used for seller''s reference, final settlement amount per each transaction can only provided through statement related API.', '查询未结算交易。', 'GET', '/finance/202507/orders/unsettled', 1, 0),
(961, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'finance', '财务', 'get_withdrawals_202309', '查询提现', 'Get the list of the withdrawal records (when Seller''s withdraw money from TikTokShop) based on the specified date range.', '查询提现。', 'GET', '/finance/202309/withdrawals', 1, 0),
(962, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'cancel_fbt_mcf_order_202601', '取消FBT多渠道履约订单', 'After an order is shipped via **FBT**, an **MCF Order** may be split into one or more `consign orders` for fulfillment. This API supports order cancellation at the level of individual `consign orders`, which can be done by providing the corresponding `mcf_order_id` and its associated `consign order` information. You can retrieve the information of `consign orders` associated with a `mcf_order_id` via the **Get FBF MCF Order Status** API.', '取消FBT多渠道履约订单。', 'POST', '/fbt/202601/mcf_outbound_orders/cancel', 1, 0),
(963, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'cancel_inbound_order_202602', '取消入库订单', 'This API is used to cancel an inbound order prior to warehouse arrival, preventing further processing and updating the order status. **If cancelling an inbound order that is part of a D2FC inbound plan, please make sure to cancel all orders under the inbound plan, otherwise non-compliance fees may be charged.**', '取消入库订单。', 'POST', '/fbt/202602/inbound_orders/cancel', 1, 0),
(964, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'confirm_inbound_method_202603', '确认入库方式', 'Finalize the selection of a specific warehouse placement option for a Fulfilled by TikTok (FBT) inbound plan.', '确认入库方式。', 'POST', '/fbt/202603/confirm_inbound_method', 1, 0),
(965, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'create_fbt_goods_202607', '创建FBT商品', 'Create FBT goods records, including SKU linkage, dimensions, hazmat details, shelf-life attributes, and return address information.', '创建FBT商品。', 'POST', '/fbt/202607/goods/create_goods', 1, 0),
(966, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'create_fbt_mcf_order_202607', '创建FBT多渠道履约订单', 'For orders created on other sales channels that require fulfillment via FBT, this API enables you to create corresponding orders (hereinafter referred to as MCF Orders). Once MCF Orders are successfully created, they will be automatically submitted to the FBT system for fulfillment.', '创建FBT多渠道履约订单。', 'POST', '/fbt/202607/mcf_outbound_orders', 1, 0),
(967, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'create_or_update_inbound_plan_202602', '创建或更新入库计划', 'Initializes a new inbound plan or updates an existing one by defining goods, or carton configurations and dimensions.', '创建或更新入库计划。', 'POST', '/fbt/202602/create_update_inbound_plan', 1, 0),
(968, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'get_fbt_inbound_order_details_202602', '查询FBT入库订单详情', 'This API is used to retrieve the inbound order details including the planned inbound detail, actual inbound detail and inbound status, etc.', '查询FBT入库订单详情。', 'GET', '/fbt/202602/inbound_orders', 1, 0),
(969, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'get_fbt_mcf_order_status_202601', '查询FBT多渠道履约订单状态', 'This API allows you to query the status of **MCF Orders**. When an order has not been shipped, the `consign_orders` field will contain no data; once the order has been shipped, the `consign_orders` field will display the consignment details of the order. If a single package cannot accommodate the entire order (due to carrier restrictions or packaging size limitations), the **FBT** system will split the order into multiple packages for fulfillment, in which case the `consign_orders` field will contain multiple entries corresponding to the respective packages.', '查询FBT多渠道履约订单状态。', 'GET', '/fbt/202601/mcf_outbound_orders', 1, 0),
(970, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'get_fbt_merchant_mcf_status_202601', '查询商家FBT多渠道履约状态', 'This API verifies whether a seller is registered as a Fulfillment by TikTok (FBT) merchant and participated in Multi Channel Fulfillment(MCF). If the seller is onboarded in FBT and enrolled in MCF, the API returns the true flag of MCF status.', '查询商家FBT多渠道履约状态。', 'GET', '/fbt/202601/merchants/mcf_status', 1, 0),
(971, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'get_fbt_merchant_onboarded_regions_202409', '查询已开通FBT的商家区域', 'This API verifies whether a seller is registered as a Fulfillment by TikTok (FBT) merchant. If the seller is onboarded, the API returns the regions where the merchant is authorized to operate under the FBT system.', '查询已开通FBT的商家区域。', 'GET', '/fbt/202409/merchants/onboarded_regions', 1, 0),
(972, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'get_fbt_warehouse_list_202408', '查询FBT仓库列表', 'This API is used to retrieve all Fulfilled by TikTok warehouse information including the warehouse name, warehouse address information, etc. The IDs of subscribed warehouses can be used to query inventory-related information.', '查询FBT仓库列表。', 'GET', '/fbt/202408/warehouses', 1, 0),
(973, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'get_inbound_method_detail_202602', '查询入库方式详情', 'Get detailed information regarding inbound plan placement options.', '查询入库方式详情。', 'POST', '/fbt/202602/inbound_method_detail', 1, 0),
(974, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'list_available_inbound_methods_202602', '查询可用入库方式列表', 'Retrieves valid inbound shipping methods and arrival time windows for a specific plan.', '查询可用入库方式列表。', 'POST', '/fbt/202602/list_available_inbound_method', 1, 0),
(975, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'print_inbound_order_labels_202602', '打印入库订单标签', 'This API uses an **asynchronous Long-Running Operation (LRO)** pattern to generate label files. This pattern allows you to trigger a generation task and track its progress until completion. **Workflow Steps** 1. **Initiate** Send a request with `order_id` and the desired `print_items`. * **Response:** The API begins the print task and returns a `task_status` of `PROCESSING`. 2. **Poll** Send subsequent requests using the same fields from Step 1. If the print task is still processing, the API will continue to return `PROCESSING`. * **Frequency:** We recommend polling every 3–5 seconds. 3. **Complete** When the status returns `SUCCESS`, the response body will include a `download_url` for your generated ZIP file.', '打印入库订单标签。', 'POST', '/fbt/202602/inbound_orders/label_print', 1, 0),
(976, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'query_goods_inventory_for_mcf_202601', '查询MCF商品库存', 'Search available inventory for MCF goods. Use this API to retrieve available quantities for the specified Fulfilled by TikTok goods IDs.', '查询MCF商品库存。', 'POST', '/fbt/202601/mcf/goods/inventory/search', 1, 0),
(977, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'search_fbt_inventory_202408', '搜索FBT库存', 'This API is used to retrieve detailed inventory information for goods and matched SKUs, including sellable inventory, reserved inventory, unsellable inventory, and in-transit inventory at the warehouse level.', '搜索FBT库存。', 'POST', '/fbt/202408/inventory/search', 1, 0),
(978, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'search_fbt_inventory_record_202410', '搜索FBT库存记录', 'This API is used to retrieve detailed inventory change records for goods at the warehouse level.', '搜索FBT库存记录。', 'POST', '/fbt/202410/inventory_records/search', 1, 0),
(979, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'search_goods_hazmat_and_expiration_info_202603', '查询商品危险品及有效期信息', 'Search hazmat and expiration information for goods by TikTok Shop SKU IDs.', '查询商品危险品及有效期信息。', 'POST', '/fbt/202603/goods/hazmat_and_expiration_info/search', 1, 0),
(980, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'search_goods_info_202607', '搜索商品信息', 'This API is used to retrieve a list of goods belonging to the merchant that meet the specified conditions. It returns detailed information about the goods, including their IDs, names, and other attributes, such as the goods-SKU relationship, dimensions, and weight as verified by the warehouse.', '搜索商品信息。', 'POST', '/fbt/202607/goods/search', 1, 0),
(981, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'ship_inbound_order_202603', '提交入库订单发货信息', 'Finalizes the shipment details for a specific inbound order, including carton information and shipping methods.', '提交入库订单发货信息。', 'POST', '/fbt/202603/ship_inbound_order', 1, 0),
(982, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'update_fbt_goods_info_202607', '更新FBT商品信息', 'Update FBT goods information, including goods name, image URL, dimensions, hazmat details, shelf-life attributes, and return address information.', '更新FBT商品信息。', 'POST', '/fbt/202607/goods/update_goods_info', 1, 0),
(983, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'update_goods_sku_relation_202603', '更新商品SKU关联', 'Bind or unbind TikTok Shop SKUs to FBT goods.', '更新商品SKU关联。', 'POST', '/fbt/202603/goods/update_goods_sku_relation', 1, 0),
(984, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfilled-by-tiktok-fbt', 'TikTok履约(FBT)', 'update_inbound_order_tracking_202602', '更新入库订单物流追踪', 'This API manages carton-level tracking information for inbound orders. It utilizes upsert logic to create new tracking records or overwrite existing entries as required. Only orders which are shipped but have not yet been marked as "Delivered" or "Received" yet can be updated, with a 5-time edit limit per carton.', '更新入库订单物流追踪。', 'POST', '/fbt/202602/inbound_orders/tracking_update', 1, 0),
(985, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'batch_ship_packages_202309', '批量发货包裹', 'Use this API to batch ship packages by providing multiple package IDs. This API is available for TikTok shipping orders as well as seller shipping orders. * `TikTok Shipping`: Schedule a package handover time for TikTok Shipping carriers to pickup a package from the Seller. * `Seller Shipping`: Seller arranges their own shipping, and upload a `tracking_number` and `shipping_provider_id`. Package ID can be obtained from [Get Order Detail](https://partner.tiktokshop.com/docv2/page/650aa8ccc16ffe02b8f167a0?external_id=650aa8ccc16ffe02b8f167a0).', '批量发货包裹。', 'POST', '/fulfillment/202309/packages/ship', 1, 0),
(986, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'combine_package_202309', '合并包裹', 'Use this API to combine packages into one fulfillment package.', '合并包裹。', 'POST', '/fulfillment/202309/packages/combine', 1, 0),
(987, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'create_first_mile_bundle_202407', '创建首公里批次', 'If you send multiple packages to TikTok Shop warehouse in a single first-mile bundle, you can use the API to create a first-mile bundle on TikTok Shop and get the bundle ID.', '创建首公里批次。', 'POST', '/fulfillment/202407/bundles', 1, 0),
(988, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'create_first_mile_bundle_v2_202510', '创建首公里批次V2', 'If you send multiple packages to TikTok Shop warehouse in a single first-mile bundle, you can use the API to create a first-mile bundle on TikTok Shop and get the bundle ID.', '创建首公里批次V2。', 'POST', '/fulfillment/202510/first_mile_bundle', 1, 0),
(989, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'create_packages_202512', '创建包裹', 'Use this API to ship orders (purchase labels). This API is region specific to the US and JP. The shipping fee and delivery time is an estimate only and is based on the package dimensions and weight you provided. Based on the package attributes, options listed below may differ from your shipping subscriptions.', '创建包裹。', 'POST', '/fulfillment/202512/packages', 1, 0),
(990, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'fulfillment_upload_delivery_file_202309', '上传履约配送文件', 'This API is used for the seller to upload the proof of delivery file for a package, and to generate the URL of the corresponding file. The generated URL is used for the [Update Package Delivery Status API](https://partner.tiktokshop.com/docv2/page/650aa332c16ffe02b8f0ba82?external_id=650aa332c16ffe02b8f0ba82). This API only supports uploading qualification files in `PDF` format. The file size can not exceed 10MB. Note: Only sellers utilizing the SOF (Seller Own Fleet) capability can use this API.', '上传履约配送文件。', 'POST', '/fulfillment/202309/files/upload', 1, 0),
(991, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'fulfillment_upload_delivery_image_202309', '上传履约配送图片', 'This API is used for the seller to upload the proof of delivery image for a package, and to generate the URL of the corresponding file. The generated URL is used in the [Update Package Delivery Status API](https://partner.tiktokshop.com/docv2/page/650aa332c16ffe02b8f0ba82?external_id=650aa332c16ffe02b8f0ba82) to indicate that the parcel has been delivered. Usage requirements: * The image format must be `JPEG`, `PNG`, or `JPG`. * The image size can not exceed 5MB.', '上传履约配送图片。', 'POST', '/fulfillment/202309/images/upload', 1, 0),
(992, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'get_eligible_shipping_service_202309', '查询可用物流服务', 'Use this API ( for US ) to query the list of available shipping services when specifying packages'' size or weight. Use this API ( for JP ) to query the list of available shipping services when specifying packages'' size or weight.The shipping fee and delivery time is an estimate only and is based on the package dimensions and weight you provided. Options listed may differ if you change the package attributes at the time of shipping.', '查询可用物流服务。', 'POST', '/fulfillment/202309/orders/{order_id}/shipping_services/query', 1, 0),
(993, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'get_order_customs_requirements_202607', '查询订单海关要求', 'This API is used to query whether an order requires extra customs clearance information, whether such information has been submitted, and the list of submitted customs clearance information. If extra customs clearance information is required but not yet provided, the merchant must complete and submit it before shipment can proceed.', '查询订单海关要求。', 'POST', '/fulfillment/202607/orders/customs_info/query', 1, 0),
(994, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'get_order_split_attributes_202309', '查询订单拆分属性', 'Use this API to check whether an order(s) can be split into multiple packages or not.', '查询订单拆分属性。', 'GET', '/fulfillment/202309/orders/split_attributes', 1, 0),
(995, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'get_package_detail_202309', '查询包裹详情', 'Returns information about a package, including handover time slot, tracking number, and shipping provider information.', '查询包裹详情。', 'GET', '/fulfillment/202309/packages/{package_id}', 1, 0),
(996, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'get_package_handover_time_slots_202309', '查询包裹交接时段', 'Use this API to retrieve the time slots available for pickup, drop-off, or van collection for the seller''s specified package by using package ID.', '查询包裹交接时段。', 'GET', '/fulfillment/202309/packages/{package_id}/handover_time_slots', 1, 0),
(997, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'get_package_shipping_document_202309', '查询包裹物流文档', 'For orders shipped by TikTok Shop, this API retrieves the URL of shipping documents (shipping label and packing slip) for a package specified by the package ID. This API is only applicable to "TikTok Shipping" orders. To obtain the shipping documents URL via this API, first call "Ship Package" to ship the corresponding package.', '查询包裹物流文档。', 'GET', '/fulfillment/202309/packages/{package_id}/shipping_documents', 1, 0),
(998, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'get_pod_detail_202606', '查询签收证明详情', 'Description of [POST]/fulfillment/:version/Get_Pod_Detail', '查询签收证明详情。', 'POST', '/fulfillment/202606/pod_details/get', 1, 0),
(999, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'get_tracking_202309', '查询物流追踪', 'This API can use the order number to obtain the corresponding logistics tracking information.', '查询物流追踪。', 'GET', '/fulfillment/202309/orders/{order_id}/tracking', 1, 0),
(1000, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'mark_package_as_shipped_202309', '将包裹标记为已发货', '**This API is currently exclusive to the following markets: US, UK, ES, IE, IT, DE, FR, JP.** This API is for sellers who fulfill orders through their own selected/preferred logistics carrier, and allows sellers to upload valid package information (items in packages, shipping provider information, and tracking number) orders/order line items to TikTok Shop. Use [Get Shipping Providers API](https://partner.tiktokshop.com/docv2/page/650aa48d4a0bb702c06d85cd?external_id=650aa48d4a0bb702c06d85cd) to retrieve the `shipping_provider_id` for shipping providers.', '将包裹标记为已发货。', 'POST', '/fulfillment/202309/orders/{order_id}/packages', 1, 0),
(1001, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'redeem_info_callback_202601', '回传核销信息', 'Send the redeem info related to the order to the TTS to complete the fulfillment.', '回传核销信息。', 'POST', '/fulfillment/202601/redeem_info/callback', 1, 0),
(1002, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'search_combinable_packages_202309', '搜索可合并包裹', 'Use this API to query orders eligible for combined shipping.', '搜索可合并包裹。', 'GET', '/fulfillment/202309/combinable_packages/search', 1, 0),
(1003, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'search_package_202309', '搜索包裹', 'Retrieve package IDs based on specified conditions. Package creation time and information update time are the common querying conditions.', '搜索包裹。', 'POST', '/fulfillment/202309/packages/search', 1, 0),
(1004, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'ship_package_202309', '发货包裹', 'Use this API to ship a package. There are two kinds of shipping options available: `TikTok Shipping` or `Seller Shipping`. * `TikTok Shipping`: Schedule a package handover time for TikTok Shipping carriers to pickup a package from seller. * `Seller Shipping`: Seller arranges their own shipping, and uploads a tracking number and `shipping_provider_id`. Package ID can be obtained from [Get Order Detail](https://partner.tiktokshop.com/docv2/page/650aa8ccc16ffe02b8f167a0?external_id=650aa8ccc16ffe02b8f167a0#Back%20To%20Top).', '发货包裹。', 'POST', '/fulfillment/202309/packages/{package_id}/ship', 1, 0),
(1005, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'split_orders_202309', '拆分订单', 'Use this API to confirm an order split. Note that supported split levels vary by region: * Some regions support item-level splits (splitting individual units of the same SKU). * Others only support all-units splits (splitting different SKUs into separate packages). Here are two examples of supported splits: * **Case 1**: all-units split, applicable for orders in BR, SEA, MX (local sellers) Split a buyer order of SKU A of quantity 2 and SKU B of quantity 1 into two separate packages: * Package 1: all units of SKU A - Package 2: all units of SKU B * **Case 2**: item-level split, applicable for orders in EU, JP, MX (global sellers), UK, US Split the same order contents into three individual packages: * Package 1: 1 unit of SKU A - Package 2: 1 unit of SKU A - Package 3: 1 unit of SKU B', '拆分订单。', 'POST', '/fulfillment/202309/orders/{order_id}/split', 1, 0),
(1006, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'tts_tracking_validation_202508', 'TTS物流追踪校验', 'Enables a seller or warehouse to validate whether a tracking number is covered by TikTok Shipping (TTS) or Collection by TikTok (CBT). Available only in the **US Market**.', 'TTS物流追踪校验。', 'GET', '/fulfillment/202508/tts_tracking_validation', 1, 0),
(1007, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'uncombine_packages_202309', '取消合并包裹', 'Use this API to uncombine one or more orders from an already combined package.', '取消合并包裹。', 'POST', '/fulfillment/202309/packages/{package_id}/uncombine', 1, 0),
(1008, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'update_package_delivery_status_202309', '更新包裹配送状态', 'Use this API to update the delivery status of the package from in transit status. Please note that only sellers utilizing the SOF( Seller Own Fleet) capability can use this API to update the package status to ''DELIVERED''. This API is only available for the SEA region.', '更新包裹配送状态。', 'POST', '/fulfillment/202309/packages/deliver', 1, 0),
(1009, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'update_package_shipping_info_202309', '更新包裹物流信息', 'If the seller entered an incorrect tracking number, this API allows the seller to update the tracking number and shipping provider for a package that has already been shipped. Attention: This API is only applicable to orders (or packages) shipped by the seller. It is only used to update the tracking number and shipping provider for packages that have already been shipped.', '更新包裹物流信息。', 'POST', '/fulfillment/202309/packages/{package_id}/shipping_info/update', 1, 0),
(1010, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'update_shipping_info_202309', '更新物流信息', 'If the seller entered an incorrect tracking number, this API allows the seller to update the tracking number and shipping provider for an order that has already been shipped. * This API is only applicable to orders (or packages) shipped by the seller. * It is only used to update the tracking number and shipping provider for packages that have already been shipped. * For orders that have been split for shipping, please use the [Update Package Shipping Info API](https://partner.tiktokshop.com/docv2/page/650aa666c16ffe02b8f1203c?external_id=650aa666c16ffe02b8f1203c). Please note that TikTok Shop only allows merchants to update shipping information within 72 hours after shipping.', '更新物流信息。', 'POST', '/fulfillment/202309/orders/{order_id}/shipping_info/update', 1, 0),
(1011, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'upload_customs_infomation_202607', '上传海关信息', 'This API is used to submit extra customs clearance information for discrepancies between declared information and physical goods.', '上传海关信息。', 'POST', '/fulfillment/202607/orders/customs_info/submit', 1, 0),
(1012, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'fulfillment', '订单履约', 'upload_invoice_202502', '上传发票', 'Upload the invoice document. **Note**: Applicable only for local sellers in the Brazil market.', '上传发票。', 'POST', '/fulfillment/202502/invoice/upload', 1, 0),
(1013, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'logistics', '物流', 'get_available_shipping_template_202510', '查询可用物流模板', 'get seller''s available shipping template and return the reason why the template is not available，this api is now only available for JP and UK market', '查询可用物流模板。', 'GET', '/logistics/202510/seller_templates', 1, 0),
(1014, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'logistics', '物流', 'get_global_seller_warehouse_202309', '查询全球卖家仓库', 'This API retrieves all global warehouse information associated with the seller. Warehouse information includes global warehouse ID, warehouse name, and warehouse ownership.', '查询全球卖家仓库。', 'GET', '/logistics/202309/global_warehouses', 1, 0),
(1015, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'logistics', '物流', 'get_logistics_tracking_202604', '查询物流追踪详情', 'This API can use the order number to obtain the corresponding logistics tracking information, it can obtain more comprehensive logistics tracking information, which is more detailed than the Get tracking API, but only for CBT orders now. Refer: action_code/action_code_name mapping details https://partner.tiktokshop.com/docv2/page/37tihrdq', '查询物流追踪详情。', 'GET', '/logistics/202604/orders/{order_id}/tracking', 1, 0),
(1016, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'logistics', '物流', 'get_shipping_providers_202309', '查询物流服务商', 'This API is used to obtain the shipping provider corresponding to the specified delivery option', '查询物流服务商。', 'GET', '/logistics/202309/delivery_options/{delivery_option_id}/shipping_providers', 1, 0),
(1017, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'logistics', '物流', 'get_warehouse_delivery_options_202309', '查询仓库配送选项', 'This API is used to obtain a list of delivery options available through the seller''s designated warehouse.', '查询仓库配送选项。', 'GET', '/logistics/202309/warehouses/{warehouse_id}/delivery_options', 1, 0),
(1018, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'logistics', '物流', 'get_warehouse_list_202309', '查询仓库列表', 'This API retrieves all warehouse information associated with the seller. Warehouse information includes name, status, address, and other details.', '查询仓库列表。', 'GET', '/logistics/202309/warehouses', 1, 0),
(1019, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'logistics', '物流', 'shipping_template_exist_v2_202606', '检查物流模板是否存在V2', 'Shipping Template Exist', '检查物流模板是否存在V2。', 'GET', '/logistics/202606/seller_template/template_exist', 1, 0),
(1020, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'orders', '订单', 'add_external_order_references_202406', '添加外部订单编号', 'If you are using your own external OMS (order management system) to manage TikTok Shop orders, the corresponding order IDs between your OMS and TikTok Shop may be different. Use this endpoint to attach the information in your OMS to the correct order(s) in TikTok Shop for further reference.', '添加外部订单编号。', 'POST', '/order/202406/orders/external_orders', 1, 0),
(1021, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'orders', '订单', 'get_external_order_references_202406', '查询外部订单编号', 'If you have used the `Add External Order References` API to sync order information between your external order management system (OMS) and TikTok Shop, you may call this API to get information on the synced orders.', '查询外部订单编号。', 'GET', '/order/202406/orders/{order_id}/external_orders', 1, 0),
(1022, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'orders', '订单', 'get_order_detail_202507', '查询订单详情', 'Get the detailed order information of an order, including important attributes such as order status, shipping addresses, payment details, price and tax info, and package information.', '查询订单详情。', 'GET', '/order/202507/orders', 1, 0),
(1023, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'orders', '订单', 'get_order_list_202309', '查询订单列表', 'Returns a list of orders created or updated during the timeframe indicated by the specified parameters. You can also apply a range of filtering criteria to narrow the list of orders returned, such as order status, delivery option type, and buyer user ID.', '查询订单列表。', 'POST', '/order/202309/orders/search', 1, 0),
(1024, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'orders', '订单', 'get_price_detail_202407', '查询价格详情', 'Get the detailed pricing calculation information of an order or a line item, including vouchers, tax, etc.', '查询价格详情。', 'GET', '/order/202407/orders/{order_id}/price_detail', 1, 0),
(1025, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'orders', '订单', 'pod_details_202606', '查询签收证明详情', 'Description of [POST]/order/:version/pod_details/search', '查询签收证明详情。', 'POST', '/order/202606/pod_details/search', 1, 0),
(1026, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'orders', '订单', 'search_order_by_external_order_reference_202406', '按外部订单编号搜索订单', 'If you have used the `Add External Order References` API to sync information from your external order management system (OMS) to corresponding orders in TikTok Shop, you may call this API to search for order information in TikTok Shop based on information in your OMS.', '按外部订单编号搜索订单。', 'POST', '/order/202406/orders/external_order_search', 1, 0),
(1027, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'orders', '订单', 'update_the_blind_box_opening_results_202605', '更新盲盒开盒结果', 'After the merchant completes blind box opening in a live room, use this callback to send blind box and batch box opening results for an order back to the platform. Buyers can then view the unboxing results in the order details.', '更新盲盒开盒结果。', 'POST', '/order/202605/orders/blind_box_result/callback', 1, 0),
(1028, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'activate_product_202309', '激活商品', 'Activate hidden products that are in the `Seller_deactivated` or `Platform_deactivated` status and display them in the TikTok Shop catalog. After submitting the activation request, the products will be sent to TikTok Shop for auditing and their status will change to `Pending`. If a product passes the audit, its status will change back to `Activate`. You can use the [Product status change webhook](https://partner.tiktokshop.com/docv2/page/650956aff1fd3102b90b6261) to monitor the audit status.', '激活商品。', 'POST', '/product/202309/products/activate', 1, 0),
(1029, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'check_listing_prerequisites_202312', '检查刊登前置条件', 'Check if a TikTok shop is ready to list products. Each shop needs to satisfy a series of TikTok Shop requirements before you can start listing products. Before you proceed to list products, use this API to check if your shop has satisfied all requirements. **Tip**: We recommend that you run this check before any bulk updates to avoid listing issues. For example, sellers may change the delivery option to "Shipped by seller" but fail to add a shipping template, thus blocking the shop from listing products. In this case, the API would return `is_failed=true` for the `SHIPPING_TEMPLATE` check item and you can prompt the seller to fix the problem.', '检查刊登前置条件。', 'GET', '/product/202312/prerequisites', 1, 0),
(1030, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'check_product_listing_202309', '检查商品刊登', 'Identify any issues with your product properties in advance to ensure your product is ready for listing. Every product must meet TikTok Shop requirements before it can be listed. Before listing, you can submit all relevant product information to this API to check whether a listing meets these requirements. You''ll receive a list of issues to resolve before listing. This process helps reduce the risk of failure when creating products. **Note**: * The language used in the product content must align with the target market''s language (e.g. don''t use Chinese), otherwise the listing will fail or be rejected.', '检查商品刊登。', 'POST', '/product/202309/products/listing_check', 1, 0),
(1031, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'create_category_upgrade_task_202407', '创建类目升级任务', 'Create a task to upgrade live products (status: `ACTIVATE`) from a 3-level to a 7-level category tree. The task runs for up to 2 hours, depending on the number of products. If the upgrade is incomplete after 2 hours, call the API again. To figure out which products'' categories have not been upgraded, call the [Search Product API](https://partner.tiktokshop.com/docv2/page/65854ffb8f559302d8a6acda) and set "category_version" to "v1". **Note**: You must wait at least 24 hours after a product goes live to successfully upgrade its category. If you call this API on the same day a new product goes live, the system will be unable to detect it.', '创建类目升级任务。', 'POST', '/product/202407/products/category_upgrade_task', 1, 0),
(1032, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'create_custom_brands_202309', '创建自定义品牌', 'Create custom brands for your own use across all markets. Authorization is not required when creating a brand. You can create the brand first and obtain brand authorization later through the Qualification Center in TikTok Shop Seller Center. **Note**: You can create up to 50 brands per day, with a total limit of 1,000 brands.', '创建自定义品牌。', 'POST', '/product/202309/brands', 1, 0),
(1033, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'create_global_product_202309', '创建全球商品', 'Create global products to be sold in one or multiple shops outside of the seller''s base country. You can only create global products in `AVAILABLE` product categories. For other categories, contact your account manager for assistance. After product creation, use the [Publish Global Product API](https://partner.tiktokshop.com/docv2/page/650a64d6defece02be678fd6) to publish and translate the product in the desired markets. **Key concept**: Global products are products created by cross-border sellers to be sold in shops outside of their base country. With global products, cross-border sellers operating across multiple markets can avoid creating the same product for each shop individually. Instead, they just need to create a single global product, which can be published and synced to all their shops, simplifying product management across markets. **Note**: * This API is applicable only for intra-EU sellers and global sellers. To create and list local products intended for sale exclusively in local shops, use the [Create Product API](https://partner.tiktokshop.com/docv2/page/6502fc8da57708028b42b18a) instead. * There may be a limit to the number of products you can list per day. We recommend prioritizing the creation of key products first to ensure they get published. You can find your listing limit on the Seller Center homepage. * The language used in the product content must align with the target market''s language (e.g. don''t use Chinese), otherwise the listing will fail or be rejected.', '创建全球商品。', 'POST', '/product/202309/global_products', 1, 0),
(1034, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'create_gpa_upgrade_task_202604', '创建GPA升级任务', 'This interface is only available for EU L2L sellers. The interface is used to upgrade products on EU interconnection. After the upgrade, products can be managed using the new interface, but not using interfaces related to Global Product.', '创建GPA升级任务。', 'POST', '/product/202604/products/gpa_upgrade_task', 1, 0),
(1035, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'create_image_translation_tasks_202505', '创建图片翻译任务', 'Initiates a translation task for one or more images. This asynchronous API queues the images for processing in the specified target language. Applicable only for sellers that sell across EU. Use the [Image Translation Completed webhook](684f8d9bcc4e44049347a12e) to monitor the translation progress, or pass the task ID to the [Get Image Translation Tasks API](684f8b2d535a9d048f234564) to retrieve the status and the translated images. **Note**: * Please wait 5 minutes after task creation before calling the Get endpoint, and retry at intervals over 10 seconds to avoid rate limiting. * Each task corresponds to the translation of 1 image into 1 target language. * You can create up to 20 tasks per call and 500 tasks per day. Any tasks beyond the daily limit will be rejected.', '创建图片翻译任务。', 'POST', '/product/202505/images/translation_tasks', 1, 0),
(1036, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'create_manufacturer_202409', '创建制造商', 'Add a manufacturer for a seller. The provided information will be automatically translated into all EU languages supported by TikTok Shop. * Use the [Search Manufacturers API](67066a580dcee902fa03ccf9) to obtain the translations. * Use the [Partial Edit Manufacturer API](67066a55c55b3a03044eea29) to edit the translations, if necessary. * When creating a product, pass the returned `manufacturer_id` to associate the product with the manufacturer. Target seller: Local sellers operating in EU countries', '创建制造商。', 'POST', '/product/202409/compliance/manufacturers', 1, 0),
(1037, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'create_product_202309', '创建商品', 'Create and list products intended for sale exclusively in local shops. You can create products in `AVAILABLE` categories. (US sellers can also create products in INVITE_ONLY categories). After creation, it will be sent for audit review by TikTok Shop. Use the [Product status change](https://partner.tiktokshop.com/docv2/page/650956aff1fd3102b90b6261) webhook to keep track of the review status. **Note**: * This API is applicable for all sellers. * Global sellers who have migrated to use the local replication listing method can use this API to create products. Otherwise, they can continue to use the [Create Global Product API](6509de61bace3e02b7489cba) to create global products. * Before calling this API, we recommend that you prepare the necessary information by following the [usage flow for your region](650b23eef1fd3102b93d2326). * There may be a limit to the number of products you can list per day. We recommend prioritizing the creation of key products first to ensure they get published. Refer to TikTok Shop Academy for details on the limit. * The language used in the product content must align with the target market''s language (e.g. don''t use Chinese), otherwise the listing will fail or be rejected.', '创建商品。', 'POST', '/product/202309/products', 1, 0),
(1038, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'create_responsible_person_202409', '创建欧盟负责人', 'Add a new EU responsible person who ensures a seller''s products comply with EU regulations. The provided information will be automatically translated into all EU languages supported by TikTok Shop. * Use the [Search Responsible Persons API](67066a55f17b7d02f95d2fb1) to obtain the translations. * Use the [Partial Edit Responsible Person API](67066a5587019802fdce19b3) to edit the translations, if necessary. * When creating a product, pass the returned `responsible_person_id` to associate the product with the responsible person. Target seller: Local sellers operating in EU countries', '创建欧盟负责人。', 'POST', '/product/202409/compliance/responsible_persons', 1, 0),
(1039, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'deactivate_products_202309', '停用商品', 'Deactivate products that are in the `Activate` status and hide them from buyers. The status changes to `Seller_deactivated` after deactivation. In the event there''s some issue with a product (e.g. out of stock), you can deactivate the product and hide it temporarily from buyers. When the issues are resolved, you can activate the product again by using the [Activate Product API](https://partner.tiktokshop.com/docv2/page/650306ff5a12ff0294eab4a9).', '停用商品。', 'POST', '/product/202309/products/deactivate', 1, 0),
(1040, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'delete_global_products_202309', '删除全球商品', 'Delete global products that you no longer need.', '删除全球商品。', 'DELETE', '/product/202309/global_products', 1, 0),
(1041, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'delete_products_202309', '删除商品', 'Delete non-frozen products that you no longer need. **For the Indonesia market**: You can only delete products that are not frozen on all listing platforms. If the product is frozen on any platform, it cannot be deleted.', '删除商品。', 'DELETE', '/product/202309/products', 1, 0),
(1042, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'diagnose_and_optimize_product_202411', '诊断并优化商品', 'Diagnose products to obtain information that helps you to improve the product content, enhancing product visibility and customer trust. The returned information includes: * Listing quality information (available only for the US market). * Issues with the current product details and the overall recommendations * Auto-generated optimization suggestions targeted for specific product fields, including the title, description, and image. This API enables you to diagnose both live products (status: `ACTIVATE`) and brand-new products not yet listed in TikTok Shop. * To diagnose a **live product**, provide the `product_id` and `category_id` and leave all other product details blank. * To diagnose a **brand-new product** not yet listed in TikTok Shop, omit the `product_id` and provide the product details as necessary. * To diagnose a **product similar to an existing one**, provide the `product_id` and `category_id`, along with any new details. The diagnosis will combine the existing product''s information with the new details you provide. For example, if you provide a new `title`, the diagnosis will use the new title instead of the existing one while keeping the other values from the product ID. **Note**: * To diagnose multiple live products, use the [Product Information Issue Diagnosis API](665048f380b6b302e73917d9). * This API focuses solely on optimizing product visibility and does not evaluate whether your product meets listing requirements. Quality issues identified by this API do not block your product from being listed. To verify listing requirements, use the [Check Product Listing API](650a0ee8f1fd3102b91c6493).', '诊断并优化商品。', 'POST', '/product/202411/products/diagnose_optimize', 1, 0),
(1043, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'edit_global_product_202309', '编辑全球商品', 'Edit all properties (e.g. description, brand, images, attributes) of a global product. **IMPORTANT**: For published products, the changes will be automatically retranslated and synced to all markets where the product is published. If you have already edited the product information or translations of the associated local products, they will be overwritten by the information in this API. For example, if you have customized the local prices such as the local pre-tax price or the local display price, they will be overwritten each time this API is called. **Note**: * There may be a limit to the number of products you can relist per day. We recommend prioritizing key products first to ensure they get published. You can find your listing limit on the Seller Center homepage. * All inputs, including blanks, in the request payload will overwrite existing values. To retain an existing value, make sure to include it in your request. Therefore, **it is strongly recommended to retrieve the latest product data using** [Get Global Product](6509e2b0bace3e02b7490c96) **and submit the complete data when editing**. This ensures accuracy and helps avoid errors or unintentional data loss due to missing fields. * The language used in the product content must align with the target market''s language (e.g. don''t use Chinese), otherwise the listing will fail or be rejected.', '编辑全球商品。', 'PUT', '/product/202309/global_products/{global_product_id}', 1, 0),
(1044, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'edit_product_202509', '编辑商品', 'Edit all properties (e.g. description, brand, images) of an existing product that is not in the `FREEZE` or `DELETED` state. After editing the product, the latest product content (referred to as v2) will be resent for audit review. If the audit passes, v2 is published to the shop, otherwise, the existing product stays live and remains unchanged (keeping v1). However, edits to the `price` or `inventory` fields do not require a reaudit and will be immediately published on the platform. Use the [Product status change](https://partner.tiktokshop.com/docv2/page/650956aff1fd3102b90b6261) webhook to keep track of the review status. **Note**: * This API is applicable only for **active sellers/shops** that have completed the KYC onboarding process. * There may be a limit to the number of products you can relist per day. We recommend prioritizing key products first to ensure they get published. You can find your listing limit on the Seller Center homepage. * All inputs, including blanks, in the request payload will overwrite existing values. To retain an existing value, make sure to include it in your request. Exceptions to this rule are the `price` and `inventory` fields, which will remain unchanged if they are omitted from the request. Therefore, **it is strongly recommended to retrieve the latest product data using** [Get Product](6509d85b4a0bb702c057fdda) **and submit the complete data when editing**. This ensures accuracy and helps avoid errors or unintentional data loss due to missing fields. * If you wish to edit only certain properties, you can use the [Partial Edit Product API](650a98d74a0bb702c06c3289), [Update Inventory API](6503068fc20ad60284b38858), or the [Update Price API](650307de5a12ff0294eac8b0). * The language used in the product content must align with the target market''s language (e.g. don''t use Chinese), otherwise the listing will fail or be rejected. **For global sellers**: If you''re using the local replication listing method, note the following sync rules: * To sync any changes to other markets, please provide the `seller_sku` and complete `replicated_products` data. * Note that **category changes** and **sales attribute changes** (in sales attribute id/name) must be synced to other markets. The API call will fail if you don''t provide these details. **For Tokopedia sellers**: Note that a product can have **only one active version** across all platforms at any time. If a product is live on both platforms, audit results for the latest version are handled as follows: * **Mixed audit results**: If the product passes audit on one platform but fails on another, on the successful platform, the product will stay live and be updated with content from the latest version (v2), while on the failed platform, the product will be deactivated and hidden entirely. * **Audit failure on all platforms**: If the product fails audit on all platforms, the existing product stays live and remains unchanged (keeping v1).', '编辑商品。', 'PUT', '/product/202509/products/{product_id}', 1, 0),
(1045, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'get_attributes_202309', '查询属性', 'Retrieve the standard built-in product and sales attributes for listing a product in a particular category based on your shop''s location. Products on TikTok Shop are grouped into categories predefined by TikTok Shop, and each category is associated with a standard set of product attributes and sales attributes. * **Sales attributes** (e.g. size, color, length) define product variants and are optional if your product is straightforward and has no variants. * **Product attributes** (e.g. manufacturer, country of origin, materials used) describe the product as a whole, regardless of variant. Some product attributes are mandatory based on listing policies. Use this API to determine the mandatory and optional attributes before listing a product. **Note**: It must be a [leaf category](6509c89d0fcef602bf1acd9b) that corresponds to the category tree type specified in the `category_version` property.', '查询属性。', 'GET', '/product/202309/categories/{category_id}/attributes', 1, 0),
(1046, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'get_brands_202309', '查询品牌', 'Retrieve all available brands for your shop, including the built-in brands and any custom brands created using the [Create Custom Brands API](650a0926f1fd3102b91bbfb0). Pass the returned brand ID when creating or editing a product to associate the brand with the product. * To check if a brand is fully authorized for use in a specific product category, specify the **category ID**. * To obtain the full list of brands that your shop can potentially use and their authorization status, omit the category ID. We recommend that you specify the **brand name** to narrow down the list of brands returned. **Key concept** Whether you can select and display a brand depends on the brand''s authorization status, the categories authorized for the brand, and whether the brand is classified as T1 (internationally renowned brands that require prior brand authorization). **- Brand selection rules**: You can only select the following types of brands during product creation/editing. * Authorized brands which contain the desired category (`authorized_status=AUTHORIZED` and `brand_status=AVAILABLE`) * Unauthorized non-T1 brands (`authorized_status=UNAUTHORIZED` and `is_t1_brand=false`) **- Brand display rules**: Note however that brands will only appear on the product display page if the brand is authorized (`authorized_status=AUTHORIZED`) and available in the desired category (`brand_status=AVAILABLE`). This means that you need to obtain brand authorization for unauthorized non-T1 brands before they can be displayed. Obtain brand authorization or add categories to an authorized brand through TikTok Shop Seller Center > Qualification Center > Brand qualification. **For Tokopedia sellers**: You can select and display any returned brand on Tokopedia regardless of these rules.', '查询品牌。', 'GET', '/product/202309/brands', 1, 0),
(1047, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'get_categories_202309', '查询类目', 'Retrieve the list of product categories available for your shop. Product categories are updated frequently, so it''s recommended to call the API in real time to ensure you are using the latest category data. Caching category data locally may result in using outdated information, leading to errors when creating products. **For the Indonesia market**: To list a product on both TikTok Shop and Tokopedia, you must use only categories that are available on both platforms. Please call this API twice to identify the overlapping categories.', '查询类目。', 'GET', '/product/202309/categories', 1, 0),
(1048, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'get_category_rules_202309', '查询类目规则', 'Retrieve the additional requirements (beyond mandatory product attributes) for listing a product in a particular category based on your shop''s location. Requirements may include product certifications, size charts, dimensions and more. Use this API to determine the supporting information that you must prepare before listing a product. **Note**: It must be a [leaf category](6509c89d0fcef602bf1acd9b) that corresponds to the category tree type specified in the `category_version` property.', '查询类目规则。', 'GET', '/product/202309/categories/{category_id}/rules', 1, 0),
(1049, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'get_global_attributes_202309', '查询全球属性', 'Retrieve the standard built-in product and sales attributes for listing a global product in a particular category, regardless of market variations. Products on TikTok Shop are grouped into categories predefined by TikTok Shop, and each category is associated with a standard set of product attributes and sales attributes. * **Sales attributes** (e.g. size, color, length) define product variants and are optional if your product is straightforward and has no variants. * **Product attributes** (e.g. manufacturer, country of origin, materials used) describe the product as a whole, regardless of variant. Some product attributes are mandatory based on listing policies. Use this API to determine the mandatory and optional attributes before listing a global product. **Note**: It must be a [leaf category](650a03f8f1fd3102b91b338a) that corresponds to the category tree type specified in the `category_version` property.', '查询全球属性。', 'GET', '/product/202309/categories/{category_id}/global_attributes', 1, 0),
(1050, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'get_global_categories_202309', '查询全球类目', 'Retrieve all available product categories, regardless of market variations. Product categories are updated frequently, so it''s recommended to call the API in real time to ensure you are using the latest category data. Caching category data locally may result in using outdated information, leading to errors when creating global products.', '查询全球类目。', 'GET', '/product/202309/global_categories', 1, 0),
(1051, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'get_global_category_rules_202309', '查询全球类目规则', 'Retrieve the additional requirements (beyond mandatory product attributes) for listing a global product in a particular category, regardless of market variations. Requirements may include product certifications, size charts, dimensions and more. Use this API to determine the supporting information that you must prepare before listing a global product. **Note**: It must be a [leaf category](650a03f8f1fd3102b91b338a) that corresponds to the category tree type specified in the `category_version` property.', '查询全球类目规则。', 'GET', '/product/202309/categories/{category_id}/global_rules', 1, 0),
(1052, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'get_global_listing_rules_202507', '查询全球刊登规则', 'Retrieves the global listing rules for a local shop that belongs to a global seller. E.g. The supported listing methods or the inventory allocation rules. The rules differ by the markets they serve. **Note**: Applicable only for global sellers.', '查询全球刊登规则。', 'GET', '/product/202507/global_listing_rules', 1, 0),
(1053, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'get_global_product_202309', '查询全球商品', 'Retrieve all properties of a global product that is in the "DRAFT", "UNPUBLISHED", or "PUBLISHED" status, and the corresponding local product IDs in the published markets.', '查询全球商品。', 'GET', '/product/202309/global_products/{global_product_id}', 1, 0),
(1054, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'get_global_replicated_products_202507', '查询全球已复制商品', 'Retrieves the globally associated replicas in other markets if the product has been replicated through local replication. Applicable only for global sellers.', '查询全球已复制商品。', 'GET', '/product/202507/products/{product_id}/replicated_products', 1, 0),
(1055, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'get_image_translation_tasks_202506', '查询图片翻译任务', 'Retrieves the image translation task status and translated images for one or more previously submitted images. **Note**: Please wait 5 minutes after [task creation](684f8b2d6e0b37048b2448b4) before calling this API, and retry at intervals over 10 seconds to avoid rate limiting. Applicable only for sellers that sell across EU.', '查询图片翻译任务。', 'GET', '/product/202506/images/translation_tasks', 1, 0),
(1056, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'get_opportunity_detail_202604', '查询商机详情', 'Retrieve the full details of a single opportunity lead by its ID, including market trend data, competition level, and recommended actions.', '查询商机详情。', 'GET', '/product/202604/opportunities/{opportunity_id}', 1, 0),
(1057, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'get_product_202309', '查询商品', 'Retrieve all properties of a product, except those in the `FREEZE` or `DELETED` status.', '查询商品。', 'GET', '/product/202309/products/{product_id}', 1, 0),
(1058, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'get_product_skpp_detail_202606', '查询商品SKPP详情', 'Return the SKPP diagnostic for one product.', '查询商品SKPP详情。', 'GET', '/product/202606/skpps/{product_id}', 1, 0),
(1059, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'get_products_seo_words_202405', '查询商品SEO关键词', 'Obtain SEO suggestions for product titles of live products (status: `ACTIVATE`) to enhance product visibility. Applicable only for the US, UK, and SEA markets.', '查询商品SEO关键词。', 'GET', '/product/202405/products/seo_words', 1, 0),
(1060, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'get_recommended_product_package_202602', '查询商品推荐包装', 'Retrieve a list of product recommended packages. (Only available in BR and MX)', '查询商品推荐包装。', 'POST', '/product/202602/packages/recommend', 1, 0),
(1061, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'get_recommended_product_title_and_description_202405', '查询推荐的商品标题和描述', 'Obtain AI-optimized product titles and descriptions for live products (status: `ACTIVATE`).', '查询推荐的商品标题和描述。', 'GET', '/product/202405/products/suggestions', 1, 0),
(1062, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'get_shop_skpp_summary_202606', '查询店铺SKPP汇总', 'Return the shop-level SKPP products roll-up.', '查询店铺SKPP汇总。', 'GET', '/product/202606/skpps/sum', 1, 0),
(1063, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'get_submission_records_202604', '查询提交记录', 'Retrieve a paginated list of submission records for the authorized seller, including submission status, review results, and linked opportunity/product information. Useful for tracking submission history and monitoring review outcomes.', '查询提交记录。', 'GET', '/product/202604/opportunities/submissions', 1, 0),
(1064, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'inventory_search_202309', '库存搜索', 'Retrieve inventory information for multiple products or SKUs. **Note**: * Searches can be based on either product IDs or SKU IDs, not both at the same time. * Passing Product IDs returns the inventory information of all SKUs under the specified products. * Passing SKU IDs returns the inventory information for the specified SKUs.', '库存搜索。', 'POST', '/product/202309/inventory/search', 1, 0),
(1065, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'list_opportunity_202604', '查询商机列表', 'Search and retrieve a paginated list of opportunity leads available to the authorized seller, with optional filters by type, status, category, etc and ordered by the algorithm ranking model.', '查询商机列表。', 'POST', '/product/202604/opportunities/query', 1, 0),
(1066, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'list_products_skpp_status_202606', '批量查询商品SKPP状态', 'Batch query SKPP status for the seller''s products.', '批量查询商品SKPP状态。', 'POST', '/product/202606/skpps/search', 1, 0),
(1067, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'optimized_images_202404', '优化图片', 'Optimize images used in your TikTok Shop by changing the background to white. This is especially useful for images displayed in the product image gallery as it enhances product visibility. **Note**: * The images to be optimized must first be uploaded to TikTok Shop through the [Upload Product Image API](https://partner.tiktokshop.com/docv2/page/6509df95defece02be598a22). You will not be able to optimize any images that are not hosted by TikTok Shop. * Images that were previously optimized will not be processed again. * The optimization is processed asynchronously and typically completes within a few seconds. Therefore, the `optimize_status` returned in the first API request for an image is always `PROCESSING`, indicating that optimization is underway. Please call the API again after a few seconds to get the final optimization status.', '优化图片。', 'POST', '/product/202404/images/optimize', 1, 0),
(1068, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'partial_edit_global_product_202509', '部分编辑全球商品', 'Description of [POST]/product/:version/Partial_Edit_Global_Product', '部分编辑全球商品。', 'PUT', '/product/202509/global_products/{global_product_id}/partial_edit', 1, 0),
(1069, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'partial_edit_manufacturer_202409', '部分编辑制造商', 'Edit the details of a manufacturer in the EU languages supported by TikTok Shop. Include the locale code to edit the responsible person''s information in a particular language. Target seller: Local sellers operating in EU countries **Note**: * Updates are handled per top-level property, so all non-empty fields within an updated object must be supplied to prevent overwriting with blanks. * For top-level properties (e.g. `name`, `email`) that are not nested in an object, you can update them individually. Omitting these properties in the request will leave them unchanged. * If you need to edit any nested property within an object, you must provide values for all nested properties of that object. Any omitted nested properties will be overwritten with blanks. For example, if you want to update `phone_number.local_number`, you must also include the `country_code` property to avoid data loss for that property.', '部分编辑制造商。', 'POST', '/product/202409/compliance/manufacturers/{manufacturer_id}/partial_edit', 1, 0),
(1070, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'partial_edit_product_202509', '部分编辑商品', 'Edit some properties (e.g. description, images, attributes) of a product that is not in the `FREEZE` or `DELETED` state. After editing the product, the latest product content (referred to as v2) will be resent for audit review. If the audit passes, v2 is published to the shop, otherwise, the existing product stays live and remains unchanged (keeping v1). However, edits to the `price` or `inventory` fields do not require a reaudit and will be immediately published on the platform. Use the [Product status change](650956aff1fd3102b90b6261) webhook to keep track of the review status. **Note**: * This API is applicable for all sellers. * There may be a limit to the number of products you can relist per day. We recommend prioritizing key products first to ensure they get published. You can find your listing limit on the Seller Center homepage. * If a draft or audit-review version exists, unedited fields will retain their values over those of the base (live) version. * **Updates are handled per top-level property**, so all non-empty fields within an updated object must be supplied to prevent overwriting with blanks. For top-level properties (e.g. `description`, `brand_id`) that are not nested in an object, you can update them individually. Omitting these properties in the request will leave them unchanged. If you need to edit any nested property within an object, you must provide values for all nested properties of that object. Any omitted nested properties will be overwritten with blanks. * If new mandatory product attributes were added by TikTok Shop after the creation of your product, ensure that you provide these attributes too. **For global sellers**: If you''re using the local replication listing method, note the following sync rules: **Sales attribute changes** (in sales attribute id/name) must be synced to other markets. Therefore, you must provide the `seller_sku` and complete `replicated_products` data. The API call will fail if you don''t provide these details. **New SKUs* (new sales attribute value id/name) are optional to sync to other markets. To sync, please provide the `seller_sku` and complete `replicated_products` data. **General changes** are optional to sync to other markets. To sync, you only need to provide `replicated_products.region`. **For Tokopedia sellers**: Note that a product can have **only one active version** across all platforms at any time. If a product is live on both platforms, audit results for the latest version are handled as follows: * **Mixed audit results**: If the product passes audit on one platform but fails on another, on the successful platform, the product will stay live and be updated with content from the latest version (v2), while on the failed platform, the product will be deactivated and hidden entirely. * **Audit failure on all platforms**: If the product fails audit on all platforms, the existing product stays live and remains unchanged (keeping v1).', '部分编辑商品。', 'POST', '/product/202509/products/{product_id}/partial_edit', 1, 0),
(1071, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'partial_edit_responsible_person_202409', '部分编辑欧盟负责人', 'Edit the details of an EU responsible person in the EU languages supported by TikTok Shop. Include the locale code to edit the responsible person''s information in a particular language. Target seller: Local sellers operating in EU countries **Note**: * Updates are handled per top-level property, so all non-empty fields within an updated object must be supplied to prevent overwriting with blanks. * For top-level properties (e.g. `name`, `email`) that are not nested in an object, you can update them individually. Omitting these properties in the request will leave them unchanged. * If you need to edit any nested property within an object, you must provide values for all nested properties of that object. Any omitted nested properties will be overwritten with blanks. For example, if you want to update `phone_number.local_number`, you must also include the `country_code` property to avoid data loss for that property.', '部分编辑欧盟负责人。', 'POST', '/product/202409/compliance/responsible_persons/{responsible_person_id}/partial_edit', 1, 0),
(1072, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'product_auditing_research_202601', '商品审核调研', 'For compliant vendor to rescan all of the product information so that the compliant vendor can issue a compliance testing report.', '商品审核调研。', 'POST', '/product/202601/compliance/auditing/research', 1, 0),
(1073, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'product_information_issue_diagnosis_202405', '商品信息问题诊断', 'Diagnose multiple existing live (status: `ACTIVATE`) products to obtain information that helps you to improve the product content, enhancing product visibility and customer trust. The returned information includes: * Listing quality information (available only for the US market). * Issues with the current product details and the overall recommendations * Auto-generated optimization suggestions targeted for specific product fields, including the title, description, and image. **Note**: This API focuses solely on optimizing product visibility and does not evaluate whether your product meets listing requirements. Quality issues identified by this API do not block your product from being listed. To verify listing requirements, use the [Check Product Listing API](650a0ee8f1fd3102b91c6493).', '商品信息问题诊断。', 'GET', '/product/202405/products/diagnoses', 1, 0),
(1074, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'publish_global_product_202309', '发布全球商品', 'Publish and convert a global product to local products in one or multiple shops in supported markets. After publishing, the product is sent for review by TikTok Shop in the respective markets. For sellers in the EU market, the provided information will also be automatically translated into all EU languages supported by TikTok Shop. **Note**: * You can only publish in each market once. To change product information, edit the global product by using the [Edit Global Product API](6509e1bcc16ffe02b8dc3cd7). The changes will be automatically synchronized to all markets where the product is published * Use the [Get Product API](6509d85b4a0bb702c057fdda) to obtain the converted local product information in the target market''s language. * Use the [Edit Product API](6509da7d0fcef602bf1caddf) or [Partial Edit Product API](650a98d74a0bb702c06c3289) to edit the local product information, if necessary.', '发布全球商品。', 'POST', '/product/202309/global_products/{global_product_id}/publish', 1, 0),
(1075, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'recommend_category_202309', '推荐类目', 'Retrieve the recommended category for a candidate product based on its title, description, and images. If you are syncing product catalogs from an external system to TikTok Shop, use this API to facilitate product categorization. **Note**: The language used in text fields such as descriptions and titles must align with the target market''s language (e.g. don''t use Chinese).', '推荐类目。', 'POST', '/product/202309/categories/recommend', 1, 0),
(1076, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'recommend_global_categories_202309', '推荐全球类目', 'Retrieve the recommended categories for a candidate global product based on its title, description, and images. If you are syncing product catalogs from an external system to TikTok Shop, use this API to facilitate product classification. **Note**: Double-byte characters (e.g. Chinese characters) are not supported in text fields such as descriptions and titles. If you include them, the API request will fail.', '推荐全球类目。', 'POST', '/product/202309/global_categories/recommend', 1, 0),
(1077, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'recover_products_202309', '恢复商品', 'Recover products that are in the `Deleted` status. The status changes to `Seller_deactivated` after recovery.', '恢复商品。', 'POST', '/product/202309/products/recover', 1, 0),
(1078, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'replicate_product_202507', '复制商品', 'Description of [POST]/product/:version/Replicate_Product', '复制商品。', 'POST', '/product/202507/products/{product_id}/global_replicate', 1, 0),
(1079, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'search_global_products_202312', '搜索全球商品', 'Retrieve a list of global products that meet the specified conditions. This API will only return the key product properties. You can pass a returned global product ID to the [Get Global Product API](https://partner.tiktokshop.com/docv2/page/6509e2b0bace3e02b7490c96) to obtain more details about the product.', '搜索全球商品。', 'POST', '/product/202312/global_products/search', 1, 0),
(1080, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'search_manufacturers_202501', '搜索制造商', 'Retrieve a list of manufacturers in the EU languages supported by TikTok Shop based on their IDs or keyword. When creating a product, pass the returned `manufacturer_id` to associate the product with the manufacturer. Target seller: Local sellers operating in EU countries', '搜索制造商。', 'POST', '/product/202501/compliance/manufacturers/search', 1, 0),
(1081, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'search_products_202502', '搜索商品', 'Retrieve a list of products that meet the specified conditions. This API will only return the key product properties. You can pass a returned product ID to the [Get Product API](https://partner.tiktokshop.com/docv2/page/6509d85b4a0bb702c057fdda) to obtain more details about the product.', '搜索商品。', 'POST', '/product/202502/products/search', 1, 0),
(1082, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'search_responsible_persons_202501', '搜索欧盟负责人', 'Retrieve a list of responsible persons in the EU languages supported by TikTok Shop based on their ID or keywords. When creating a product, pass the returned `responsible_person_id` to associate the product with the responsible person. Target seller: Local sellers operating in EU countries', '搜索欧盟负责人。', 'POST', '/product/202501/compliance/responsible_persons/search', 1, 0),
(1083, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'search_size_charts_202407', '搜索尺码表', 'Retrieve size charts that a seller has created.', '搜索尺码表。', 'POST', '/product/202407/sizecharts/search', 1, 0),
(1084, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'submit_appeal_task_202604', '提交申诉任务', '#### Appeal Size Chart Verification Initiates an appeal process for a product that was blocked during the listing phase due to a size chart verification failure. This API is used when a seller believes their product was incorrectly blocked by our automated size chart validation system. The validation checks for three potential issues: 1. Whether the size chart contains all mandatory dimensions. 2. Whether the size chart covers all Stock-Keeping Units (SKUs) for sale. 3. Whether the numerical values within the size chart are valid. If the validation system detects an issue, the product listing will be blocked. By using this API, sellers can submit an appeal. If the appeal is approved, the block will be lifted, and the seller can re-list the product. Use the `[Appeal Status Webhook]` to monitor the appeal''s progress, or pass the `appeal_id` to the `[Get Appeal Status API]` to retrieve the current status. Note: * Please wait at least 5 minutes after submitting an appeal before checking its status via the API to ensure the data is synchronized. * You can submit up to 50 appeals per day. Any requests exceeding this limit will be rejected.', '提交申诉任务。', 'POST', '/product/202604/appeals/submit', 1, 0),
(1085, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'submit_product_via_opportunity_202604', '通过商机提交商品', 'Submit an existing product (already listed on TikTok Shop) as a response to a specific opportunity lead. The product will be linked to the opportunity and enter the standard submission review flow. If you need to list a new product to meet the opportunity lead, you must first request the product release API to create the product_id , and then submit the product to link the opportunity lead.', '通过商机提交商品。', 'POST', '/product/202604/opportunities/{opportunity_id}/submit', 1, 0),
(1086, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'update_global_inventory_202309', '更新全球库存', 'Update the inventory of unpublished global products if you have access to the Multi-Warehouse feature. The inventory of published global products will not be affected by this update operation.', '更新全球库存。', 'POST', '/product/202309/global_products/{global_product_id}/inventory/update', 1, 0),
(1087, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'update_inventory_202309', '更新库存', 'Update the inventory quantity of SKUs belonging to a product. The SKU ID must belong to a product that is **not** in `FREEZE` or `DELETED` status.', '更新库存。', 'POST', '/product/202309/products/{product_id}/inventory/update', 1, 0),
(1088, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'update_price_202309', '更新价格', 'Update the price of multiple SKUs belonging to a product in the `ACTIVATE` status and not included in any ongoing promotions. **Note**: The `data` response field is always empty as there is no additional response data.', '更新价格。', 'POST', '/product/202309/products/{product_id}/prices/update', 1, 0),
(1089, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'update_stock_operation_settings_202604', '更新库存操作设置', 'This API allows sellers to configure auto-replenishment settings for one or more SKUs in bulk. It is designed to be extensible for future inventory operation rules', '更新库存操作设置。', 'POST', '/product/202604/inventory/operation/settings', 1, 0),
(1090, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'upload_product_file_202309', '上传商品文件', 'Upload non-image files, such as PDF or video to TikTok Shop. Use this API when you need to add videos to your product to improve the shopping experience, or submit certifications or reports to meet TikTok Shop requirements for listing restricted products. **Note**: You must store the response body to retrieve the ID or URL required to associate the file with a product during product creation or editing.', '上传商品文件。', 'POST', '/product/202309/files/upload', 1, 0),
(1091, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'products', '商品', 'upload_product_image_202309', '上传商品图片', 'Upload local images to TikTok Shop for use as product images, variant images, size charts, certification images and so on. **Note**: * All images used in TikTok Shop products must be uploaded through this API. You will not be able to use any image URLs that are not hosted by TikTok Shop. * You must store the response body to retrieve the ID or URL required to associate the image with a product during product creation or editing.', '上传商品图片。', 'POST', '/product/202309/images/upload', 1, 0),
(1092, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'promotion', '营销活动', 'create_promotion_activity_202309', '创建推广活动', 'Use this API to create a product discount activity or a flash deal activity. You cannot create a coupon activity with this API. To do that, you''ll need to go to the seller center or the seller app. To update the products or SKUs included in the activity, use [Update Activity Product](https://partner.tiktokshop.com/docv2/page/650d32c42aaa3602b86ccb5c).', '创建推广活动。', 'POST', '/promotion/202309/activities', 1, 0),
(1093, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'promotion', '营销活动', 'deactivate_activity_202309', '停用活动', 'Deactivate an ongoing or upcoming activity.', '停用活动。', 'POST', '/promotion/202309/activities/{activity_id}/deactivate', 1, 0),
(1094, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'promotion', '营销活动', 'get_activity_202309', '查询活动', 'Get the details of a product discount or flash deal promotion activity. Product information for `FIXED_PRICE`, `DIRECT_DISCOUNT` and `FLASHSALE` activity that ended more than 180 days will not be returned.For coupon activities, use [Get Coupon](6699dce0de15e502ed219e37).', '查询活动。', 'GET', '/promotion/202309/activities/{activity_id}', 1, 0),
(1095, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'promotion', '营销活动', 'get_coupon_202406', '查询优惠券', 'Use this API to get the full details of a coupon matching the {coupon_id}.', '查询优惠券。', 'GET', '/promotion/202406/coupons/{coupon_id}', 1, 0),
(1096, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'promotion', '营销活动', 'remove_promotion_activity_products_202309', '移除推广活动商品', 'Use this API to remove products or SKUs from the existing product discount or flash sale promotion activity.', '移除推广活动商品。', 'DELETE', '/promotion/202309/activities/{activity_id}/products', 1, 0),
(1097, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'promotion', '营销活动', 'republish_activity_202607', '重新发布活动', 'Use this API to republish a product discount activity or a flash deal activity that expired or was deactivated within the last 7 days. This API only supports FIXED_PRICE, FLASHSALE, and DIRECT_DISCOUNT activities. You must provide a new effective period by passing the new begin_time and end_time. Products and SKUs already associated with the activity do not need to be added again. After the activity is republished, you can edit the activity and modify its products or SKUs as usual. We recommend using this API instead of recreating the activity to reduce requests to the API for adding products.', '重新发布活动。', 'POST', '/promotion/202607/activities/{activity_id}/republish', 1, 0),
(1098, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'promotion', '营销活动', 'search_coupon_list_202406', '搜索优惠券列表', 'Use this API to get a list of coupons, narrowed down further based on search parameters. The coupons are created in Seller Center or Seller App. For further details of the specific coupon, use `GET Coupon`.', '搜索优惠券列表。', 'POST', '/promotion/202406/coupons/search', 1, 0),
(1099, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'promotion', '营销活动', 'search_promotion_activities_202309', '搜索推广活动', 'Get a list of product discount or flash deal promotion activities. For coupon activities, use [Search Coupons](https://partner.tiktokshop.com/docv2/page/6699dcdf115ebe02f841e4cd).', '搜索推广活动。', 'POST', '/promotion/202309/activities/search', 1, 0),
(1100, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'promotion', '营销活动', 'update_promotion_activity_202309', '更新推广活动', 'Change the title and the beginning and end time of the existing product discount or flash sale promotion activity.', '更新推广活动。', 'PUT', '/promotion/202309/activities/{activity_id}', 1, 0),
(1101, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'promotion', '营销活动', 'update_promotion_activity_products_202309', '更新推广活动商品', 'Use this API to add the products or SKUs to the list of a product discount activity or a flash deal activity. You can also change the discounts on existing products or SKUs. To remove the products or SKUs from the list, use [Remove Activity Product](https://partner.tiktokshop.com/docv2/page/650acfd84a0bb702c072b4eb).', '更新推广活动商品。', 'PUT', '/promotion/202309/activities/{activity_id}/products', 1, 0),
(1102, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'return-and-refund', '退货退款', 'approve_cancellation_202309', '批准取消申请', 'Use this API to approve a buyer-initiated cancellation request identified by cancel_id. Call this API only when the cancellation request is still waiting for seller action.', '批准取消申请。', 'POST', '/return_refund/202309/cancellations/{cancel_id}/approve', 1, 0),
(1103, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'return-and-refund', '退货退款', 'approve_return_202309', '批准退货', 'Use this API to approve a buyer''s return request. The exact effect depends on the return type and return status. Before calling this API, make sure the return is still awaiting a seller action that matches the decision you are sending.', '批准退货。', 'POST', '/return_refund/202309/returns/{return_id}/approve', 1, 0),
(1104, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'return-and-refund', '退货退款', 'calculate_refund_202602', '计算退款', 'Use this API to estimate the refundable amount for a cancellation, refund, or return-and-refund request. The estimate depends on the selected request_type, reason_name, and targeted items. For return-and-refund scenarios, the estimate can also depend on the selected return shipping method.', '计算退款。', 'POST', '/return_refund/202602/refunds/calculate', 1, 0),
(1105, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'return-and-refund', '退货退款', 'cancel_order_202602', '取消订单', 'Use this API to cancel an order on behalf of a seller. In the US and UK markets, when an item is out of stock, partial cancellation on the single item level is supported by this API.', '取消订单。', 'POST', '/return_refund/202602/cancellations', 1, 0),
(1106, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'return-and-refund', '退货退款', 'create_return_202602', '创建退货', 'Use this API to create a seller-initiated aftersales request for an order on behalf of the buyer. Supported request types are `REFUND` and `RETURN_AND_REFUND`. Before submitting the request, confirm that the order is eligible for the selected aftersales type and return method. After the request is created, use the relevant search, status, or review API to continue the aftersales workflow.', '创建退货。', 'POST', '/return_refund/202602/returns', 1, 0),
(1107, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'return-and-refund', '退货退款', 'get_aftersale_eligibility_202602', '查询售后资格', 'Use this API to check eligible aftersale solutions for an order, including whether the seller or buyer can initiate a refund, return, or cancel a specific order.', '查询售后资格。', 'GET', '/return_refund/202602/orders/{order_id}/aftersale_eligibility', 1, 0),
(1108, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'return-and-refund', '退货退款', 'get_decision_eligibility_202601', '查询处理决定资格', 'Use this API to evaluate which seller decisions are currently allowed for the specified aftersales request. The API returns one result per requested decision, including whether the decision is currently eligible and any rejection reasons that are applicable for an eligible reject decision.', '查询处理决定资格。', 'GET', '/return_refund/202601/decision_eligibility', 1, 0),
(1109, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'return-and-refund', '退货退款', 'get_reject_reasons_202309', '查询拒绝原因', 'Use this API to retrieve the seller reject-reason options currently applicable to the specified aftersales request. Use the returned name value as the reject reason key when calling the corresponding seller reject API.', '查询拒绝原因。', 'GET', '/return_refund/202309/reject_reasons', 1, 0),
(1110, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'return-and-refund', '退货退款', 'get_return_records_202309', '查询退货记录', 'Use this API to retrieve the record entries for a specific return request. Each item in data.records represents an action or lifecycle event for the specified return_id.', '查询退货记录。', 'GET', '/return_refund/202309/returns/{return_id}/records', 1, 0),
(1111, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'return-and-refund', '退货退款', 'get_review_decision_202606', '查询审核处理决定', 'Description of [GET]/return_refund/:version/Get_Review_Decision', '查询审核处理决定。', 'GET', '/return_refund/202606/review_decision', 1, 0),
(1112, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'return-and-refund', '退货退款', 'reject_cancellation_202309', '拒绝取消申请', 'Use this API to reject a buyer''s cancellation request for the specified cancel_id. Before calling this API, make sure the request is still in a state where seller rejection is currently allowed.', '拒绝取消申请。', 'POST', '/return_refund/202309/cancellations/{cancel_id}/reject', 1, 0),
(1113, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'return-and-refund', '退货退款', 'reject_return_202606', '拒绝退货', 'Use this API to reject a buyer''s return or refund request. The valid decision depends on the current request type and status. Before calling this API, make sure the request is still awaiting the seller action that matches the decision you send.', '拒绝退货。', 'POST', '/return_refund/202606/returns/{return_id}/reject', 1, 0),
(1114, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'return-and-refund', '退货退款', 'review_aftersales_202606', '审核售后', 'API used to review (approve, reject, or offer alternatives to) a buyer''s return request.', '审核售后。', 'POST', '/return_refund/202606/aftersales/review', 1, 0),
(1115, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'return-and-refund', '退货退款', 'search_aftersales_request_202603', '搜索售后申请', 'Used to search for aftersales request level data.', '搜索售后申请。', 'POST', '/return_refund/202603/aftersales/search', 1, 0),
(1116, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'return-and-refund', '退货退款', 'search_cancellations_202602', '搜索取消申请', 'Use this API to search and retrieve one or more order cancellations.', '搜索取消申请。', 'POST', '/return_refund/202602/cancellations/search', 1, 0),
(1117, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'return-and-refund', '退货退款', 'search_return_merchandise_authorization_202604', '搜索退货授权单', 'Used to search for RMA request level data', '搜索退货授权单。', 'POST', '/return_refund/202604/rma/search', 1, 0),
(1118, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'return-and-refund', '退货退款', 'search_returns_202602', '搜索退货', 'Use this API to search returns by return ID, order ID, buyer, return type, return status, arbitration status, or create/update time window. The response is paginated. To retrieve the next page, pass the previous `next_page_token` as `page_token` and keep all other filters and sorting unchanged.', '搜索退货。', 'POST', '/return_refund/202602/returns/search', 1, 0),
(1119, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'return-and-refund', '退货退款', 'upload_shipping_document_and_tracking_info_202405', '上传运输文档及物流追踪信息', 'Use this API to upload return shipping documents, tracking numbers, and carriers for buyers.', '上传运输文档及物流追踪信息。', 'POST', '/return_refund/202405/returns/shipping_documents', 1, 0),
(1120, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'seller', '卖家', 'get_active_shops_202309', '查询活跃店铺', 'Retrieves all active shops that belong to a seller. You can use this API to check the activation status of shops. Target seller: All', '查询活跃店铺。', 'GET', '/seller/202309/shops', 1, 0),
(1121, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'seller', '卖家', 'get_seller_permissions_202309', '查询卖家权限', 'Retrieves the cross-border operations that a cross-border seller is permitted to perform. You can use this API prior to listing products to check whether a seller has the ability to list global products. Target seller: Cross-border sellers', '查询卖家权限。', 'GET', '/seller/202309/permissions', 1, 0),
(1122, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'seller', '卖家', 'get_shop_groups_202601', '查询店铺分组', 'Query the shop scope of product interoperability groups. For example, in the scenario of the United States and Mexico, which two shops have interoperable products.', '查询店铺分组。', 'GET', '/seller/202601/shop_groups', 1, 0),
(1123, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'supply-chain', '供应链', 'confirm_package_shipment_202309', '确认包裹发货', 'This API enables a warehouse service provider to send package shipment information for an order. Only warehouse service providers who have been certified by the platform have permission to access this interface.', '确认包裹发货。', 'POST', '/supply_chain/202309/packages/sync', 1, 0),
(1124, 'tiktok-shop-api', 'TikTok Shop开放平台API', NULL, NULL, 'tools', '工具', 'upload_file_init_202512', '初始化文件上传', 'To upload a large file to TikTok Shop, such as a video, first use this API to initialize the upload session. Then upload the file to the returned upload URL; files smaller than 5 MB must be uploaded as a single, non-chunked request. After the upload step returns a ResourceId, pass that ResourceId to the API for the target path. For more details, see https://partner.tiktokshop.com/docv2/page/wfi3nz36.', '初始化文件上传。', 'POST', '/open/202512/file/init', 1, 0);
